window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch05"]={"id":"ch05","title":"第三章(三) 后翻译转运","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"线粒体/叶绿体 · 核孔运输 · 过氧化物酶体","modules":[{"i":0,"name":"模块一：线粒体与叶绿体蛋白转运","slides":[{"i":0,"sec":"第一节 线粒体","title":"Part III 后翻译转运 (p1)","notes":"Part III The transport protein into Mitochondria(线粒体)、Chloroplast(叶绿体) and Peroxisome(过氧化物酶体)。线粒体/叶绿体的绝大多数蛋白质由核基因编码、细胞质游离核糖体合成，然后定向运输(翻译后转移)。","page":1,"level":"掌握","img":"assets/img/ch05/p001.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"线粒体、叶绿体和过氧化物酶体的大多数蛋白质由什么编码、在哪里合成、以何种方式运输？","back":"由核基因编码；在细胞质游离核糖体合成；翻译后定向运输（后转运）","mnemonic":"核编码、胞质造、译后送","type":"流程","useImg":false,"blank":"翻译后定向运输","blank2":"细胞质游离核糖体"}]},{"i":1,"sec":"第一节 线粒体","title":"线粒体蛋白的定向运输 (p2)","notes":"线粒体蛋白质的定向运输(eg.定位于线粒体基质中的蛋白)：一、后转运的跨膜运输——线粒体蛋白质的定向运输。线粒体虽有自己的基因组，但绝大多数蛋白由核基因编码。","page":2,"level":"掌握","img":"assets/img/ch05/p002.jpg","anim":null,"fig":"线粒体蛋白的定向运输：线粒体绝大多数蛋白由核基因编码，在胞质游离核糖体合成后以“前体蛋白”形式运入。前体蛋白 N 端有导肽，识别线粒体膜上的受体。图显示前体蛋白从胞质进入线粒体的过程。","points":null,"check":null,"cards":[{"front":"线粒体蛋白质定向运输的主要方式是什么？","back":"后转运的跨膜运输；线粒体虽有自身基因组，但绝大多数蛋白由核基因编码","mnemonic":"自有DNA，蛋白靠核供","type":"定义","useImg":false,"blank":"后转运的跨膜运输","blank2":"核基因编码"}]},{"i":2,"sec":"第一节 线粒体","title":"线粒体蛋白运输要点 (p3)","notes":"线粒体蛋白定向运输要点：①N端导肽(presequence)必须先与线粒体膜上的受体识别；②前体蛋白到线粒体基质的转移只发生在少数线粒体内外膜相'接触点'(距约若干nm)。","page":3,"level":"掌握","img":"assets/img/ch05/p003.jpg","anim":"mito_import","fig":null,"points":["N 端导肽先与线粒体膜受体识别。","前体蛋白以解析叠形式穿过 TOM/TIM，在接触点(内外膜贴近处)转位。","转运消耗能量：胞质 Hsp70、膜电位、基质 Hsp70 与 ATP。","进入基质后导肽被切除，蛋白折叠成成熟形式。"],"check":null,"cards":[{"front":"线粒体蛋白定向运输的两个要点是什么？","back":"①N端导肽先与线粒体膜受体识别；②前体蛋白仅在内外膜接触点转移到基质","mnemonic":"导肽认受体，接触点进门","type":"流程","useImg":false,"blank":"N端导肽","blank2":"线粒体膜受体"}]},{"i":3,"sec":"第一节 线粒体","title":"接触点转运 (p4)","notes":"Translocation of protein precursors to the matrix occurs at the contact sites——前体蛋白在内外膜接触点处转运到线粒体基质。接触点是内外膜靠近的区域。\n\n【本页英文讲解】\n本页讲线粒体蛋白的接触点转运（contact site）。前体蛋白（protein precursor）从细胞质转运进线粒体基质（matrix）时，并非在膜上任意位置进行，而是在内外膜相互靠近的接触点（contact sites）。此处使外膜与内膜的转运装置靠拢，便于前体蛋白穿越两层膜。考点：接触点是线粒体蛋白跨膜转运的通道位点，常与TOM/TIM协同。","page":4,"level":"掌握","img":"assets/img/ch05/p004.jpg","anim":null,"fig":"前体蛋白进入线粒体基质发生在“接触点”——外膜与内膜紧密贴近的区域。图显示 TOM 与 TIM 在接触点对接，前体蛋白经此从胞质直接进入基质，避免在膜间隙停留。","points":null,"check":{"q":"线粒体前体蛋白转运进入基质的主要部位是？","o":["A. 线粒体外膜任意区域","B. 线粒体内外膜的接触点","C. 线粒体嵴的顶端","D. 线粒体基质的核糖体上"],"a":"B","e":"前体蛋白在内外膜接触点处转运到线粒体基质。","oe":["并非外膜任意区域，前体蛋白转运在内外膜接触点进行。","前体蛋白经线粒体内外膜接触点转运进入基质。","嵴的顶端不是前体蛋白转运进入基质的主要部位。","基质核糖体在蛋白转运进入之后，并非转运部位。"]},"cards":[{"front":"前体蛋白转运到线粒体基质发生在什么部位？","back":"内外膜接触点（contact sites）；即内外膜靠近的区域","mnemonic":"两膜贴近处，就是转运门","type":"定位","useImg":true,"blank":"内外膜接触点","blank2":"内外膜靠近的区域"}]},{"i":4,"sec":"第一节 线粒体","title":"线粒体膜的转运子 (p5)","notes":"The protein translocators in the mitochondrial membrane：外膜转运子TOM复合体、内膜转运子TIM复合体。前体蛋白经TOM进入、经TIM进入基质。\n\n【本页英文讲解】\n本页介绍线粒体膜上的蛋白转运子。外膜转运子为TOM复合体（translocase of the outer membrane，外膜转运酶复合体），内膜转运子为TIM复合体（内膜转运酶复合体）。前体蛋白先经TOM穿过外膜，再经TIM穿过内膜进入基质。考点：TOM负责识别并进入外膜，TIM负责跨内膜，二者分工是线粒体蛋白导入的核心装置。","page":5,"level":"掌握","img":"assets/img/ch05/p005.jpg","anim":"tom_tim","fig":"线粒体膜上的蛋白转运器：①TOM 复合体(外膜)——受体+转位通道，接收胞质前体蛋白；②SAM 复合体(外膜)——把外膜蛋白插入外膜；③TIM23 复合体(内膜)——把蛋白送入基质，Hsp70 驱动；④TIM22 复合体(内膜)——插入内膜的载体蛋白；⑤OXA 复合体(内膜)——插入内膜蛋白。","points":null,"check":null,"cards":[{"front":"线粒体膜上的两个蛋白转运子复合体是什么？各负责什么？","back":"外膜转运子TOM复合体；内膜转运子TIM复合体；前体蛋白经TOM进入、经TIM进入基质","mnemonic":"TOM在外，TIM在内，T-O-M进，T-I-M深","type":"组成","useImg":true,"blank":"TOM复合体","blank2":"TIM复合体"}]},{"i":5,"sec":"第一节 线粒体","title":"只有解折叠蛋白能进入 (p6)","notes":"Only unfolded proteins can be imported into Mit——只有去折叠的蛋白才能被导入线粒体。线粒体蛋白必须先在胞质解折叠才能穿过膜的狭窄通道。","page":6,"level":"掌握","img":"assets/img/ch05/p006.jpg","anim":null,"fig":"只有解析叠的蛋白才能进入线粒体：前体蛋白在胞质由 Hsp70 维持解析叠；进入基质时 Hsp70 结合并拉动肽链。图对比“折叠的蛋白不能进入”与“解析叠的蛋白可进入”。","points":null,"check":{"q":"关于线粒体蛋白导入，下列叙述正确的是？","o":["A. 只有解折叠的蛋白才能被导入线粒体","B. 折叠完成的蛋白可直接穿过膜通道","C. 多聚体蛋白比单体更易导入","D. 蛋白导入不需要消耗能量"],"a":"A","e":"线粒体蛋白必须先在胞质解折叠才能穿过膜的狭窄通道。","oe":["线粒体蛋白须在胞质解折叠后，才能穿过膜的狭窄通道。","折叠完成的蛋白不能直接穿过膜通道，须先解折叠。","多聚体蛋白比单体更难导入，须先解聚。","蛋白导入需消耗能量，依赖ATP水解及膜电位。"]},"cards":[{"front":"为什么只有去折叠的蛋白才能被导入线粒体？","back":"线粒体蛋白须先在胞质解折叠，才能穿过膜上狭窄的通道","mnemonic":"通道太窄，折叠进不来","type":"功能","useImg":false,"blank":"解折叠","blank2":"狭窄的通道"}]},{"i":6,"sec":"第一节 线粒体","title":"线粒体基质蛋白导入 (p7)","notes":"Protein import into the mitochondrial matrix：前体蛋白N端导肽与TOM受体结合→经接触点→TIM→进入基质→导肽被切除→蛋白折叠。\n\n【本页英文讲解】\n本页讲线粒体基质蛋白（matrix protein）的导入过程。前体蛋白N端的导肽（presequence，即转运信号）先与TOM受体结合，经内外膜接触点，再通过TIM进入基质；随后导肽被切除，蛋白折叠为成熟构象。这是经典的翻译后转运途径。考点：导肽位于N端且可被切除，全过程需分子伴侣辅助折叠并耗能。","page":7,"level":"掌握","img":"assets/img/ch05/p007.jpg","anim":"mito_matrix_import","fig":"蛋白进入线粒体基质的过程：前体蛋白(含导肽)+胞质 Hsp70 → 与 TOM 受体结合 → 经 TOM/TIM23 进入基质 → 基质 Hsp70 结合、ATP 驱动 → 导肽被切除 → 蛋白折叠。图给出“导肽+Hsp70”驱动的完整流程。","points":null,"check":{"q":"线粒体基质蛋白导入过程中，前体蛋白N端导肽首先与下列哪种成分结合？","o":["A. TIM复合体","B. TOM受体","C. 基质中的分子伴侣","D. 线粒体DNA"],"a":"B","e":"前体蛋白N端导肽先与TOM受体结合，再经接触点、TIM进入基质。","oe":["TIM位于线粒体内膜，前体蛋白先经TOM进入，非首先结合。","前体蛋白N端导肽首先与线粒体外膜的TOM受体结合。","基质分子伴侣在蛋白进入基质后起作用，属后续步骤。","线粒体DNA不参与前体蛋白的识别与结合。"]},"cards":[{"front":"线粒体基质蛋白导入的基本流程是什么？","back":"N端导肽与TOM受体结合→经接触点→TIM→进入基质→导肽被切除→蛋白折叠","mnemonic":"结合、过点、穿TIM、切肽、折叠","type":"流程","useImg":true,"blank":"N端导肽","blank2":"TOM受体"}]},{"i":7,"sec":"第一节 线粒体","title":"Hsp70解折叠前体蛋白 (p8)","notes":"运送前，含导肽的蛋白前体(precursor)在细胞质基质中与Hsp70结合，ATP→ADP，解折叠为松散结构(unfolded protein)，才能被导入线粒体。","page":8,"level":"掌握","img":"assets/img/ch05/p008.jpg","anim":null,"fig":"含导肽的前体蛋白在胞质由 Hsp70 结合、维持解析叠；进入线粒体基质后，基质 Hsp70 结合肽链并利用 ATP 拉动其进入；随后导肽被线粒体基质中的蛋白酶切除。图强调 Hsp70 的“分子马达”作用。","points":null,"check":null,"cards":[{"front":"运送前，含导肽的前体蛋白在胞质中如何被解折叠？","back":"与Hsp70结合；ATP→ADP供能；解折叠为松散结构后才能被导入线粒体","mnemonic":"Hsp70松绑，ATP买单","type":"流程","useImg":false,"blank":"Hsp70","blank2":"ATP→ADP供能"}]},{"i":8,"sec":"第一节 叶绿体","title":"叶绿体蛋白的转运肽 (p9)","notes":"细胞质基质游离核糖体中合成的叶绿体前体蛋白，N端含一个额外的氨基酸序列，称转运肽(transit peptides)。转运肽引导蛋白进入叶绿体后被切除。","page":9,"level":"掌握","img":"assets/img/ch05/p009.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"叶绿体前体蛋白的N端有什么特殊序列？其功能是什么？","back":"转运肽(transit peptide)；引导蛋白进入叶绿体后被切除","mnemonic":"转运肽=进叶绿体的'门票'，进门即撕","type":"定义","useImg":false,"blank":"转运肽","blank2":"叶绿体"}]},{"i":9,"sec":"第一节 叶绿体","title":"叶绿体蛋白的分选 (p10)","notes":"叶绿体蛋白的分选：①叶绿体基质蛋白的导入和转运肽的切割；②类囊体腔蛋白的导入和转运肽的切除；③类囊体膜蛋白的导入。展示叶绿体蛋白的多层次分选。","page":10,"level":"掌握","img":"assets/img/ch05/p010.jpg","anim":"chloroplast_import","fig":null,"points":null,"check":{"q":"关于叶绿体蛋白分选，下列哪项不属于其分选层次？","o":["A. 叶绿体基质蛋白的导入和转运肽的切割","B. 类囊体腔蛋白的导入和转运肽的切除","C. 类囊体膜蛋白的导入","D. 线粒体基质蛋白的导入"],"a":"D","e":"叶绿体蛋白分选包括基质蛋白、类囊体腔蛋白和类囊体膜蛋白的导入，不涉及线粒体基质蛋白。","oe":["基质蛋白的导入和转运肽切割属叶绿体蛋白分选层次。","类囊体腔蛋白的导入与转运肽切除属叶绿体分选层次。","类囊体膜蛋白的导入属于叶绿体蛋白分选层次。","线粒体基质蛋白导入属线粒体分选，不属于叶绿体分选层次。"]},"cards":[{"front":"叶绿体蛋白分选有哪三个层次？","back":"①基质蛋白导入+转运肽切割；②类囊体腔蛋白导入+转运肽切除；③类囊体膜蛋白导入","mnemonic":"基质→腔→膜，三层递进","type":"流程","useImg":true,"blank":"基质蛋白导入","blank2":"类囊体腔蛋白导入"}]},{"i":10,"sec":"第一节 叶绿体","title":"类囊体腔蛋白的双区转运肽 (p11)","notes":"定位于叶绿体类囊体腔中的蛋白质，其前体蛋白N端的转运肽可分2个区：①N端含导向叶绿体基质序列；②接下来是导向类囊体腔(thylakoid)的序列。分两步引导。","page":11,"level":"掌握","img":"assets/img/ch05/p011.jpg","anim":null,"fig":"定位到叶绿体类囊体腔的蛋白：其转运肽可分两个区——N 端导向叶绿体基质序列 + 导向类囊体腔序列。蛋白先进入基质，切除第一段，再经类囊体膜进入腔，切除第二段。图说明“两段信号、两步引导”。","points":null,"check":null,"cards":[{"front":"类囊体腔蛋白的转运肽为何称'双区转运肽'？","back":"N端含两区：①导向叶绿体基质序列；②导向类囊体腔序列；分两步引导","mnemonic":"两段票：先到基质，再转腔","type":"组成","useImg":true,"blank":"导向叶绿体基质序列","blank2":"导向类囊体腔序列"}]},{"i":11,"sec":"第一节 叶绿体","title":"叶绿体基质蛋白 (p12)","notes":"定位于叶绿体基质(stroma)中的蛋白(eg. Rubisco，CO2固定的重要酶类，其中的8个小亚基由核基因编码，翻译后转运)。转运肽被切除后蛋白折叠成活性形式。","page":12,"level":"掌握","img":"assets/img/ch05/p012.jpg","anim":null,"fig":"定位于叶绿体基质的蛋白(如 Rubisco 小亚基)：前体由 N 端转运肽引导，穿过叶绿体双层膜进入基质，转运肽被基质中的蛋白酶切除，成为成熟蛋白。Rubisco 是光合作用固定 CO₂ 的关键酶。","points":null,"check":null,"cards":[{"front":"Rubisco小亚基由什么编码？如何定位到叶绿体基质？","back":"核基因编码；在胞质核糖体合成后翻译后转运入基质，转运肽切除后折叠成活性形式","mnemonic":"小亚基核编码，进基质再组装","type":"例证","useImg":false,"blank":"核基因编码","blank2":"胞质核糖体"}]}],"mcq":[{"id":"ch05_mcq_1","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体蛋白N端的引导序列称为？","o":["A. 信号肽","B. 导肽(presequence)","C. 转运肽","D. 前导序列"],"a":"B","e":"线粒体蛋白N端为导肽(presequence)；叶绿体蛋白N端为转运肽(transit peptide)。两者都是翻译后转移的引导信号。","kp":"ch05_s0_2","oe":["信号肽通常指引导分泌蛋白进入内质网的序列，非线粒体。","线粒体蛋白N端的引导序列称为导肽（presequence）。","转运肽指叶绿体蛋白N端的引导序列，非线粒体。","前导序列是泛指名称，线粒体引导序列标准称导肽。"]},{"id":"ch05_mcq_2","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体蛋白前体进入基质需要？","o":["A. 保持折叠状态","B. 由Hsp70帮助解折叠","C. 直接穿过膜","D. 经核孔"],"a":"B","e":"Only unfolded proteins can be imported——前体蛋白在胞质与Hsp70结合，ATP水解后解折叠，才能经TOM/TIM进入线粒体。","kp":"ch05_s0_2","oe":["错误。前体必须解折叠才可被导入，保持折叠无法通过TOM/TIM。","正确。胞质Hsp70结合前体并水解ATP，使其解折叠后经TOM/TIM进入基质。","错误。需借助TOM/TIM转运复合体，不能直接穿过线粒体膜。","错误。核孔是核质运输通道，线粒体蛋白不经核孔进入基质。"]},{"id":"ch05_mcq_3","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体蛋白前体跨膜转运发生在？","o":["A. 任意膜位置","B. 内外膜接触点","C. 核孔","D. 高尔基体"],"a":"B","e":"前体蛋白到线粒体基质的转移只发生在少数线粒体内外膜相'接触点'，经TOM(外膜)和TIM(内膜)复合体。","kp":"ch05_s0_2","oe":["错误。并非任意膜位置，只在少数内外膜接触点进行转运。","正确。前体经内外膜接触点的TOM与TIM复合体转运进入基质。","错误。核孔介导核质运输，与线粒体蛋白跨膜转运无关。","错误。高尔基体参与膜泡运输，不参与线粒体蛋白导入。"]},{"id":"ch05_mcq_4","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"叶绿体蛋白N端的引导序列称为？","o":["A. 导肽","B. 转运肽(transit peptide)","C. 信号肽","D. NLS"],"a":"B","e":"叶绿体前体蛋白N端含转运肽(transit peptide)，引导入叶绿体后被切除。","kp":"ch05_s0_8","oe":["错误。导肽多指线粒体蛋白引导序列，叶绿体特称转运肽。","正确。叶绿体前体蛋白N端为转运肽，引导入叶绿体后被切除。","错误。信号肽引导蛋白进入内质网，属共翻译转运。","错误。NLS是核定位信号，负责引导蛋白进入细胞核。"]},{"id":"ch05_mcq_5","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"类囊体腔蛋白的转运肽特点是？","o":["A. 只有一段","B. 分2个区(导向基质+导向类囊体腔)","C. 无引导功能","D. 位于C端"],"a":"B","e":"类囊体腔蛋白的转运肽分2区：N端导向叶绿体基质序列，接下来是导向类囊体腔的序列，分两步引导。","kp":"ch05_s0_10","oe":["错误。并非只有一段，而是分导向基质与类囊体腔两个区。","正确。转运肽分两区，先导向叶绿体基质，再导向类囊体腔。","错误。转运肽具有引导功能，可定向运输蛋白至类囊体腔。","错误。转运肽位于蛋白N端，而不是C端。"]},{"id":"ch05_mcq_6","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"核孔复合体(NPC)的直径(通道)约为？","o":["A. 9-10nm","B. 120nm","C. 1nm","D. 50nm"],"a":"A","e":"NPC通道直径约9-10nm，外径约120nm；40~60kDa以下小分子可自由扩散。","kp":"ch05_s0_4","oe":["正确。NPC通道直径约9-10nm，小分子物质可自由扩散通过。","错误。120nm是核孔复合体的外径，不是其通道直径。","错误。1nm过小，远小于实际通道，多数分子无法通过。","错误。50nm大于实际通道直径，与事实不符。"]},{"id":"ch05_mcq_7","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"引导蛋白质进入细胞核的信号是？","o":["A. NLS(核定位信号)","B. NES","C. KDEL","D. M6P"],"a":"A","e":"NLS(核定位信号)引导亲核蛋白入核；NES(核输出信号)介导出核；KDEL是ER驻留信号；M6P是溶酶体信号。","kp":"ch05_s0_8","oe":["正确。NLS核定位信号引导亲核蛋白经NPC进入细胞核。","错误。NES是核输出信号，介导核内蛋白输出到细胞质。","错误。KDEL是内质网驻留信号，使蛋白滞留于内质网。","错误。M6P是溶酶体酶的分选信号，导向溶酶体。"]},{"id":"ch05_mcq_8","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"识别并结合NLS的胞质受体是？","o":["A. importin(输入蛋白)","B. exportin","C. SRP","D. dynamin"],"a":"A","e":"亲核蛋白必须与NLS受体importin结合才能穿过NPC。importin分布在胞质溶胶中。","kp":"ch05_s0_2","oe":["正确。胞质中importin识别并结合NLS，介导货物蛋白入核。","错误。exportin介导含NES的货物蛋白从核内输出。","错误。SRP识别信号肽，介导分泌蛋白的共翻译转运。","错误。dynamin是参与膜泡颈缩的GTP酶，与入核无关。"]},{"id":"ch05_mcq_9","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"调控核质运输的关键GTP酶是？","o":["A. Ran","B. Rab","C. Sar","D. ARF"],"a":"A","e":"Ran是核质运输的关键GTP酶。Ran-GTP(主要在核内)结合importin使其释放货物蛋白。","kp":"ch05_s0_1","oe":["正确。Ran是核质运输的关键GTP酶，Ran-GTP调控货物释放。","错误。Rab调控膜泡运输与融合，不参与核质运输。","错误。Sar参与内质网到高尔基体的膜泡形成。","错误。ARF参与膜泡形成与囊泡运输，非核质运输。"]},{"id":"ch05_mcq_10","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"40~60kDa以下的小分子出入细胞核的方式是？","o":["A. 主动运输","B. 被动扩散(经NPC)","C. 胞吞","D. 跨膜转运"],"a":"B","e":"NPC双功能：离子、小分子代谢产物、40~60kDa以下小分子可自由扩散出入核；大分子经NLS/NES主动运输。","kp":"ch05_s0_0","oe":["错误。小分子经NPC自由扩散，不属消耗能量的主动运输。","正确。40~60kDa以下小分子可经NPC自由扩散出入细胞核。","错误。胞吞是大分子物质入胞方式，并不是入核方式。","错误。经核孔扩散进入，而非跨脂双层膜的跨膜转运。"]},{"id":"ch05_mcq_11","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体外膜和内膜的蛋白转运子分别是？","o":["A. TOM和TIM","B. TIM和TOM","C. SRP和SR","D. NPC"],"a":"A","e":"外膜转运子TOM复合体、内膜转运子TIM复合体，前体蛋白经TOM进入、经TIM进入基质。","kp":"ch05_s0_4","oe":["正确。外膜转运子为TOM复合体，内膜转运子为TIM复合体。","错误。顺序颠倒，外膜是TOM，内膜是TIM。","错误。SRP与SR参与内质网共翻译转运，与线粒体无关。","错误。NPC是核孔复合体，负责核质之间的运输。"]},{"id":"ch05_mcq_12","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"过氧化物酶体的另一种名称是？","o":["A. 微体(microbody)","B. 溶酶体","C. 内体","D. 液泡"],"a":"A","e":"过氧化物酶体又称微体(microbody)，单层膜，含氧化酶和过氧化氢酶。","kp":"ch05_s0_0","oe":["正确。过氧化物酶体又称微体，为单层膜细胞器。","错误。溶酶体含酸性水解酶，与过氧化物酶体不同。","错误。内体参与胞吞物质的分选，不是过氧化物酶体。","错误。液泡是植物细胞的贮水细胞器，另属一类。"]}],"judge":[{"id":"ch05_judge_1","modI":0,"q":"线粒体蛋白N端含导肽，叶绿体蛋白N端含转运肽。","a":"对","e":"线粒体蛋白N端为导肽(presequence)，叶绿体蛋白N端为转运肽(transit peptide)。","kp":"ch05_s0_8","oe":["线粒体蛋白N端为导肽，叶绿体蛋白N端为转运肽。","误把线粒体与叶绿体的N端信号名称互换，故判错。"]},{"id":"ch05_judge_2","modI":0,"q":"线粒体蛋白前体必须解折叠后才能被导入线粒体。","a":"对","e":"只有解折叠的蛋白能进入线粒体；前体蛋白在胞质由Hsp70帮助、消耗ATP解折叠。","kp":"ch05_s0_7","oe":["只有解折叠的蛋白能进入线粒体，前体蛋白在胞质由Hsp70耗能解折叠。","误以为折叠态蛋白可直接导入或无需分子伴侣，故判错。"]},{"id":"ch05_judge_3","modI":0,"q":"线粒体外膜和内膜的蛋白转运子分别是TOM和TIM复合体。","a":"对","e":"外膜为TOM复合体、内膜为TIM复合体，前体蛋白经二者进入基质。","kp":"ch05_s0_4","oe":["线粒体外膜为TOM复合体、内膜为TIM复合体，前体蛋白经二者进入基质。","误把TOM与TIM对应的膜或内外顺序记反，故判错。"]},{"id":"ch05_judge_10","modI":0,"q":"叶绿体类囊体腔蛋白的转运肽可分为导向基质和导向类囊体腔两个区。","a":"对","e":"类囊体腔蛋白转运肽分2区：N端导向基质序列+导向类囊体腔序列，分两步引导。","kp":"ch05_s0_10","oe":["类囊体腔蛋白转运肽分N端导向基质区与导向类囊体腔区，分两步引导。","误判为错者多不知转运肽可分导向基质和类囊体腔两个功能区。"]}],"fill":[{"id":"ch05_fill_1","modI":0,"q":"线粒体蛋白N端含________,叶绿体蛋白N端含________,两者都引导翻译后转移。","a":"导肽(presequence),转运肽(transit peptide)","kp":"ch05_s0_8","oe":["线粒体蛋白前体N端的导肽引导其翻译后转运入线粒体。","叶绿体蛋白N端的转运肽引导其翻译后转运入叶绿体。"]},{"id":"ch05_fill_2","modI":0,"q":"线粒体蛋白前体在胞质由________帮助、消耗________解折叠后才能导入。","a":"Hsp70,ATP","kp":"ch05_s0_7","oe":["胞质Hsp70分子伴侣使前体解折叠并保持可转运状态。","前体解折叠由Hsp70消耗ATP驱动，导入过程也需ATP。"]},{"id":"ch05_fill_3","modI":0,"q":"线粒体外膜转运子为________复合体,内膜为________复合体,前体在内外膜________点转运。","a":"TOM,TIM,接触","kp":"ch05_s0_4","oe":["线粒体外膜转运子为TOM复合体，识别并导入前体蛋白。","线粒体内膜转运子为TIM复合体，将前体送入基质。","前体在内外膜相互接触的接触点处协调转运，故填接触点。"]},{"id":"ch05_fill_8","modI":0,"q":"Rubisco的小亚基由________基因编码,翻译后转运入叶绿体________。","a":"核,基质","kp":"ch05_s0_11","oe":["Rubisco小亚基由核基因编码，大亚基由叶绿体基因编码。","小亚基在胞质合成后经转运肽导入叶绿体基质，再与rbcL大亚基装配。"]},{"id":"ch05_fill_11","modI":0,"q":"类囊体腔蛋白的转运肽分2区:________序列和导向________的序列。","a":"导向叶绿体基质,类囊体腔","kp":"ch05_s0_10","oe":["转运肽第一区引导蛋白进入叶绿体基质，故填导向叶绿体基质。","第二区引导蛋白由基质进一步进入类囊体腔，故填类囊体腔。"]}],"short":[{"id":"ch05_short_1","modI":0,"q":"简述线粒体蛋白质翻译后转运的过程。","a":"线粒体蛋白质的翻译后转运：\n\n【特点】\n线粒体绝大多数蛋白由核基因编码，在胞质游离核糖体合成后转运。\n\n【过程】\n①在细胞质基质中，含N端导肽(presequence)的前体蛋白与Hsp70结合，ATP→ADP，解折叠为松散结构；\n②前体蛋白的导肽与线粒体外膜受体识别；\n③在内外膜接触点，经外膜转运子TOM复合体进入；\n④经内膜转运子TIM复合体进入基质；\n⑤导肽被切除，蛋白在基质中重新折叠成活性形式；\n⑥部分蛋白进一步分选到内膜、膜间隙或外膜。\n\n【要点】\n①需N端导肽；②必须解折叠才能导入；③发生在内外膜接触点；④消耗能量(ATP)。\n\n【对比】叶绿体蛋白用转运肽(transit peptide)引导。","kp":"ch05_s0_1"},{"id":"ch05_short_3","modI":0,"q":"比较线粒体、叶绿体、过氧化物酶体蛋白的翻译后转运。","a":"三种细胞器蛋白翻译后转运的比较：\n\n| 细胞器 | 引导信号 | 转运子/受体 | 特点 |\n|---|---|---|---|\n| 线粒体 | N端导肽(presequence) | TOM/TIM复合体 | 在内外膜接触点转运，需解折叠 |\n| 叶绿体 | N端转运肽(transit peptide) | TOC/TIC复合体 | 转运肽分2区(基质+类囊体腔) |\n| 过氧化物酶体 | PTS1/PTS2 | Pex蛋白 | 可折叠后导入，有两种发生途径 |\n\n【共同点】\n①蛋白由核基因编码、胞质游离核糖体合成；\n②翻译后转运；\n③依赖N端信号序列；\n④信号序列被切除；\n⑤消耗能量。\n\n【不同点】\n①线粒体需完全解折叠(Hsp70)，过氧化物酶体可折叠导入；\n②叶绿体转运肽分两区，可进入基质和类囊体腔；\n③过氧化物酶体还有ER出芽从头形成途径。\n\n【意义】保证细胞器蛋白正确定位。","kp":"ch05_s0_8"},{"id":"ch05_short_5","modI":0,"q":"简述叶绿体蛋白质的分选途径。","a":"叶绿体蛋白质的分选：\n\n【共同起点】\n细胞质游离核糖体中合成的前体蛋白N端含转运肽(transit peptide)。\n\n【分选途径】\n①叶绿体基质蛋白：转运肽引导经TOC/TIC进入基质→转运肽被切割→折叠成活性蛋白(如Rubisco小亚基)。\n②类囊体腔蛋白：转运肽分2区——N端导向叶绿体基质序列+接下来导向类囊体腔序列→先进入基质，再经类囊体膜进入腔→切除转运肽。\n③类囊体膜蛋白：转运肽引导到类囊体膜并整合。\n\n【特点】\n①转运肽分2区，可两步引导；\n②转运肽最终被切除；\n③部分蛋白需叶绿体自身蛋白(如cpSecA)协助。\n\n【意义】\n保证叶绿体各亚区室蛋白的正确定位，是叶绿体功能的基础。","kp":"ch05_s0_9"}],"calc":[{"id":"ch05_calc_1","modI":0,"q":"论述蛋白质翻译后转运的主要途径及分子机制。","a":"翻译后转运将胞质合成的蛋白运往线粒体/叶绿体/过氧化物酶体/细胞核,机制各异","steps":"【定义】\n蛋白质在细胞质游离核糖体完全合成后，再转运至特定细胞器。\n\n【1. 线粒体蛋白转运】\n①N端导肽；②Hsp70+ATP解折叠；③内外膜接触点经TOM/TIM；④导肽切除、重折叠。\n\n【2. 叶绿体蛋白转运】\n①N端转运肽(分2区)；②经TOC/TIC；③分选到基质/类囊体腔/膜；④转运肽切除。\n\n【3. 过氧化物酶体蛋白转运】\n①PTS1/PTS2信号；②Pex受体；③可折叠导入；④两种发生途径(ER出芽/分裂)。\n\n【4. 核孔运输】\n①NLS/NES信号；②importin/exportin受体；③经NPC；④Ran-GTP调控。\n\n【共同点】\n①蛋白由核基因编码、胞质合成；②翻译后转运；③依赖信号序列；④信号被切除(部分)；⑤消耗能量。\n\n【意义】\n保证细胞器蛋白正确定位，维持细胞区室化功能。","kp":"ch05_s0_0"},{"id":"ch05_calc_3","modI":0,"q":"论述细胞器蛋白靶向信号(分选信号)的多样性及其意义。","a":"不同细胞器使用不同的靶向信号,构成蛋白质分选的'邮政编码'系统","steps":"【各类靶向信号】\n①信号肽(signal peptide)：N端引导蛋白入ER(共翻译转移)；\n②导肽(presequence)：N端引导线粒体蛋白；\n③转运肽(transit peptide)：N端引导叶绿体蛋白(分2区)；\n④PTS1/PTS2：过氧化物酶体蛋白；\n⑤NLS：核定位信号(入核)；\n⑥NES：核输出信号(出核)；\n⑦KDEL：ER驻留/回收信号；\n⑧M6P：溶酶体酶分选信号。\n\n【共同特点】\n①都是特定的氨基酸序列(或糖基修饰)；\n②被特异受体识别；\n③部分在完成任务后被切除；\n④引导蛋白到达正确部位。\n\n【意义】\n①是蛋白质分选的分子基础('邮政编码')；\n②保证细胞区室化、各细胞器功能正常；\n③信号异常导致疾病(如家族性高胆固醇血症、I细胞病、囊性纤维化等)；\n④是基因工程中蛋白定位改造的基础。","kp":"ch05_s0_9"}],"term":[{"id":"ch05_term_1","modI":0,"term":"导肽(Presequence)","def":"①线粒体蛋白N端的引导序列（定义）。②功能：引导前体蛋白进入线粒体，与膜受体识别（功能）。③特点：完成使命后被切除（特点）。④与叶绿体的转运肽(transit peptide)相对应（对比）。","kps":"踩分点:①定义(1分)②功能(1分)③切除(1分)④与转运肽对比(1分)","kp":"ch05_s0_2"},{"id":"ch05_term_2","modI":0,"term":"转运肽(Transit Peptide)","def":"①叶绿体前体蛋白N端的引导序列（定义）。②特点：可分2区(导向叶绿体基质+导向类囊体腔)，完成使命后被切除（特点）。③功能：引导叶绿体蛋白分选到基质、类囊体腔或膜（功能）。","kps":"踩分点:①定义(1分)②分2区(1分)③切除(1分)④功能(1分)","kp":"ch05_s0_8"},{"id":"ch05_term_8","modI":0,"term":"TOM/TIM复合体","def":"①线粒体外膜(TOM)和内膜(TIM)的蛋白转运子复合体（定义）。②功能：前体蛋白经TOM进入、经TIM进入线粒体基质（功能）。③位置：在内外膜接触点协同工作（位置）。","kps":"踩分点:①定义(1分)②功能(2分)③位置(1分)","kp":"ch05_s0_4"},{"id":"ch05_term_10","modI":0,"term":"分子伴侣Hsp70在线粒体蛋白转运中的作用","def":"①Hsp70在胞质中与前体蛋白结合（定义）。②功能：消耗ATP使前体蛋白解折叠为松散结构，才能被导入线粒体（功能）。③意义：线粒体只允许解折叠蛋白进入（意义）。","kps":"踩分点:①定义(1分)②功能(2分)③意义(1分)","kp":"ch05_s0_7"},{"id":"ch05_term_11","modI":0,"term":"共翻译转移与翻译后转移","def":"①共翻译转移：蛋白边合成边经信号肽引导入ER(分泌蛋白、膜蛋白、溶酶体酶)（定义）。②翻译后转移：蛋白在游离核糖体完全合成后转运至线粒体、叶绿体、过氧化物酶体、细胞核（定义）。③区别：转移时间不同、信号序列不同、受体不同（区别）。","kps":"踩分点:①共翻译(1分)②翻译后(1分)③区别(2分)","kp":"ch05_s0_0"},{"id":"ch05_term_14","modI":0,"term":"接触点(Contact Site)","def":"①线粒体内外膜靠近的区域（定义）。②功能：前体蛋白在此经TOM/TIM转运到线粒体基质（功能）。③意义：是线粒体蛋白导入的关键位点（意义）。","kps":"踩分点:①定义(1分)②功能(2分)③意义(1分)","kp":"ch05_s0_3"},{"id":"ch05_term_15","modI":0,"term":"细胞器蛋白靶向信号","def":"①引导蛋白质到达特定细胞器的氨基酸序列（定义）。②种类：信号肽(ER)、导肽(线粒体)、转运肽(叶绿体)、PTS(过氧化物酶体)、NLS/NES(核)、KDEL(ER驻留)、M6P(溶酶体)（种类）。③意义：是蛋白质分选的'邮政编码'，信号异常导致疾病（意义）。","kps":"踩分点:①定义(1分)②种类(2分)③意义(1分)","kp":"ch05_s0_7"}]},{"i":1,"name":"模块二：核孔运输","slides":[{"i":0,"sec":"第二节 细胞核","title":"细胞核结构 (p13)","notes":"细胞核：核被膜、染色质/染色体(DNA)、核仁(nucleolus)。核被膜为双层核膜，上有核孔复合体(nuclear pore complex, NPC)。核质运输是后翻译转运的重要途径。","page":13,"level":"掌握","img":"assets/img/ch05/p013.jpg","anim":"nucleus_structure","fig":"细胞核的结构：核被膜(双层膜)、核孔复合体、染色质/染色体、核仁、核基质。核被膜将核与胞质分开，核孔复合体是物质交换的通道。图给出细胞核各组成部分的层次关系。","points":null,"check":null,"cards":[{"front":"细胞核由哪三部分组成？核被膜的结构特点是什么？","back":"核被膜、染色质/染色体、核仁；核被膜为双层核膜，上有核孔复合体(NPC)","mnemonic":"核三件套：膜、质、仁","type":"组成","useImg":true,"blank":"核孔复合体","blank2":"核被膜"}]},{"i":1,"sec":"第二节 细胞核","title":"胰腺细胞核电镜 (p14)","notes":"胰腺细胞核电镜图：Nu核仁、NPC核孔复合体、Chr染色质、NE核被膜。核孔复合体是核质物质交换的通道。","page":14,"level":"理解","img":"assets/img/ch05/p014.jpg","anim":null,"fig":null,"points":null,"check":{"q":"胰腺细胞核电镜图中，核质物质交换的通道是？","o":["A. 核仁","B. 染色质","C. 核孔复合体","D. 核被膜"],"a":"C","e":"核孔复合体是核质物质交换的通道。","oe":["核仁是rRNA合成和核糖体组装的场所，不是物质交换通道。","染色质是遗传物质的存在形式，不是核质交换通道。","核孔复合体是核质之间进行物质交换的通道。","核被膜是界膜，物质交换经其上的核孔复合体完成。"]},"cards":null},{"i":2,"sec":"第二节 细胞核","title":"核孔复合体(NPC) (p15)","notes":"核孔复合体(nuclear pore complex, NPC)：所有真核细胞(酵母、人)间期细胞核普遍存在。核孔的直径为9-10nm(通道)、外径约120nm。是核质物质交换的双向通道。","page":15,"level":"掌握","img":"assets/img/ch05/p015.jpg","anim":"npc_structure","fig":null,"points":null,"check":null,"cards":[{"front":"核孔复合体(NPC)的通道直径和外径分别是多少？","back":"通道直径9-10nm；外径约120nm","type":"组成数字","useImg":true,"blank":"通道直径9-10nm","blank2":"外径约120nm"},{"front":"NPC的功能是什么？存在于哪些细胞？","back":"核质物质交换的双向通道；所有真核细胞间期核普遍存在","mnemonic":"NPC=核质双向大门","type":"功能","useImg":false,"blank":"核质物质交换的双向通道","blank2":"真核细胞间期核"}]},{"i":3,"sec":"第二节 细胞核","title":"NPC电镜观察 (p16-17)","notes":"冷冻蚀刻电镜技术、高分辨率扫描电镜显示核孔复合体的八重对称结构。","page":17,"level":"理解","img":"assets/img/ch05/p017.jpg","anim":null,"fig":null,"points":null,"check":{"q":"冷冻蚀刻电镜和高分辨率扫描电镜显示核孔复合体具有什么结构特征？","o":["A. 三重对称结构","B. 八重对称结构","C. 螺旋对称结构","D. 无规则网状结构"],"a":"B","e":"电镜观察显示核孔复合体具有八重对称结构。","oe":["核孔复合体并非三重对称，而呈现八重对称。","电镜显示核孔复合体具有八重对称结构。","核孔复合体呈八重对称，并非螺旋对称结构。","核孔复合体非无规则网状，而具规则八重对称。"]},"cards":null},{"i":4,"sec":"第二节 细胞核","title":"NPC结构-胞质环 (p19)","notes":"核孔复合体(NPC)结构模型(纵向看)：胞质环(cytoplasmic ring)/外环——核孔边缘胞质面一侧，环上有8条短纤毛伸向胞质。","page":19,"level":"掌握","img":"assets/img/ch05/p019.jpg","anim":"npc_model","fig":"核孔复合体的纵向结构：胞质面有胞质环和短纤维，核质面有核质环、长纤维和核篮；辐从边缘伸向中心。横切面呈辐射状八重对称，纵向核质面 vs 胞质面结构不对称(功能不同)。","points":null,"check":null,"cards":[{"front":"NPC胞质环位于何处？有何结构特征？","back":"位于核孔边缘胞质面一侧；环上有8条短纤毛伸向胞质","mnemonic":"胞质环8纤毛，朝外伸","type":"定位","useImg":true,"blank":"短纤毛","blank2":"核孔边缘胞质面一侧"}]},{"i":5,"sec":"第二节 细胞核","title":"核篮结构 (p20)","notes":"核被膜的胞质面、核质面——核篮结构(basket)：核质面一侧有核篮，由8条纤丝汇聚成环。","page":20,"level":"掌握","img":"assets/img/ch05/p020.jpg","anim":null,"fig":null,"points":null,"check":{"q":"核篮结构位于核被膜的哪一侧？","o":["A. 胞质面","B. 核质面","C. 内外膜之间","D. 核膜双层脂质内部"],"a":"B","e":"核质面一侧有核篮，由8条纤丝汇聚成环。","oe":["核篮位于核质面一侧，而不是胞质面。","核质面一侧有核篮，由8条纤丝汇聚成环。","核篮位于核质面，不在内外膜之间。","核篮位于核质面，不在核膜双层脂质内部。"]},"cards":[{"front":"核篮结构位于NPC的哪一侧？由什么组成？","back":"核质面一侧；由8条纤丝汇聚成环","mnemonic":"核篮在核内，8丝汇成环","type":"定位","useImg":true,"blank":"纤丝","blank2":"核质面一侧"}]},{"i":6,"sec":"第二节 细胞核","title":"NPC功能-物质运输 (p21)","notes":"核孔复合体(NPC)功能：物质运输——双方向(入核&出核转运)。①亲核蛋白(NLS信号序列)的核输入(如染色质包装蛋白)；②核输出。","page":21,"level":"掌握","img":"assets/img/ch05/p021.jpg","anim":null,"fig":null,"points":["核孔复合体功能：双向的入核与出核转运。","亲核蛋白(含 NLS)入核；RNA、核糖体亚基(含 NES)出核。","入核/出核都是主动运输、高度选择、可调节、耗能。"],"check":null,"cards":[{"front":"核孔复合体(NPC)的物质运输功能体现在哪两个方面？","back":"双方向转运：入核转运（亲核蛋白经NLS引导）与出核转运。","mnemonic":"有进有出，双向通行","type":"功能","useImg":true,"blank":"双方向转运","blank2":"入核转运"}]},{"i":7,"sec":"第二节 细胞核","title":"NPC双功能 (p22)","notes":"NPC双功能：①被动运输——离子、小分子代谢产物、分子量约40~60kDa以下的小分子物质可自由扩散出入细胞核(原则上)；②主动运输——大分子经NLS/NES主动转运。","page":22,"level":"掌握","img":"assets/img/ch05/p022.jpg","anim":null,"fig":"核孔复合体的双功能：①被动运输——离子、小分子代谢物、分子量约 40~60kDa 以下的小分子可自由扩散；②主动运输——大分子、RNP 颗粒经中央运输蛋白主动运输，具高度选择性、需信号序列和载体、耗能。","points":null,"check":{"q":"关于核孔复合体的功能，下列叙述正确的是？","o":["A. 所有物质均需主动运输通过","B. 离子和小分子代谢产物可自由扩散出入","C. 大分子不能通过NPC转运","D. 被动运输可转运任意大小的分子"],"a":"B","e":"NPC可被动运输离子、小分子代谢产物及约40~60kDa以下的小分子物质，大分子经NLS/NES主动转运。","oe":["并非所有物质都需主动运输，小分子可经NPC被动扩散。","离子和小分子代谢产物可经核孔复合体自由扩散出入。","大分子可经NLS/NES介导主动转运通过核孔复合体。","被动运输有大小限制，不能转运任意大小的分子。"]},"cards":[{"front":"NPC的被动运输与主动运输有何区别？","back":"被动：离子、小分子代谢物、约40~60kDa以下小分子自由扩散；主动：大分子经NLS/NES耗能转运。","mnemonic":"小的自由过，大的要信号","type":"对比","useImg":true,"blank":"自由扩散","blank2":"主动"}]},{"i":8,"sec":"第二节 细胞核","title":"核孔运输 (p23)","notes":"后转运的核孔运输——细胞核，通过核孔复合体(nuclear pores)实现核质物质交换。\n\n【读图讲解】\n该图演示“后转运的核孔运输”。左侧为细胞核整体，标出核仁(nucleolus)、带核孔的核膜(nuclear envelope with nuclear pores)以及与之相连的内质网(ER)，红箭头指出核孔所在。右侧放大核孔复合体(nuclear pores)，并以虚线分为两栏：左栏为扩散(Diffusion)，允许离子、代谢物及小于40kDa的小蛋白通过；右栏为主动运输(Active transport)，负责转运大于40kDa的蛋白、hnRNP，以及mRNA、tRNA、hnRNP等。要点：核孔是双向选择性通道，小分子靠扩散，大分子靠主动运输与信号序列调控。","page":23,"level":"掌握","img":"assets/img/ch05/p023.jpg","anim":null,"fig":"后转运的核孔运输：亲核蛋白(含 NLS)在胞质合成后，经核孔复合体进入细胞核。图显示蛋白从胞质穿过 NPC 进入核质。关键：NLS 是入核信号，运输是主动的。","points":null,"check":{"q":"细胞核与细胞质之间进行物质交换主要通过下列哪种结构实现？","o":["A. 核膜上的核孔复合体","B. 内质网膜上的易位子","C. 高尔基体形成的囊泡","D. 线粒体膜上的通道蛋白"],"a":"A","e":"核孔复合体是核质之间物质交换的通道。","oe":["核质物质交换主要通过核膜上的核孔复合体实现。","易位子介导蛋白质进入内质网，不是核质交换结构。","高尔基体囊泡参与分泌运输，不介导核质物质交换。","线粒体膜通道蛋白与核质之间的物质交换无关。"]},"cards":[{"front":"细胞核与细胞质之间的物质交换通过什么结构实现？","back":"核孔复合体(nuclear pores)，实现核质物质交换。","mnemonic":"核质往来，核孔为门","type":"定位","useImg":true,"blank":"核孔复合体","blank2":"核质物质交换"}]},{"i":9,"sec":"第二节 细胞核","title":"核运输基本概念 (p24)","notes":"物质出入细胞核的运输机制基本概念：核蛋白(nuclear protein)、核定位信号(nuclear localization signal, NLS)、核输出信号(NES)。\n\n【本页英文讲解】\n本页给出物质出入细胞核运输的基本概念。核蛋白（nuclear protein）指在细胞质中合成、需进入细胞核发挥功能的蛋白质；核定位信号（nuclear localization signal, NLS）是引导其入核的氨基酸序列；核输出信号（nuclear export signal, NES）引导核内蛋白出核。考点：NLS与NES是核质运输的方向性信号。","page":24,"level":"掌握","img":"assets/img/ch05/p024.jpg","anim":"nuclear_import","fig":null,"points":null,"check":{"q":"下列哪项是引导亲核蛋白进入细胞核的典型信号序列？","o":["A. 核输出信号（NES）","B. 核定位信号（NLS）","C. 信号肽","D. 前导序列"],"a":"B","e":"核定位信号（NLS）是亲核蛋白入核所需的信号序列。","oe":["核输出信号NES引导蛋白出核，不是入核信号。","核定位信号NLS是引导亲核蛋白进入细胞核的典型信号。","信号肽引导蛋白进入内质网，不是入核信号。","前导序列（导肽）引导蛋白进入线粒体等，非入核信号。"]},"cards":[{"front":"物质出入细胞核运输机制的三个基本概念是什么？","back":"核蛋白(nuclear protein)；核定位信号(NLS)；核输出信号(NES)。","mnemonic":"蛋白、进信号、出信号","type":"定义","useImg":false,"blank":"核定位信号","blank2":"核输出信号"}]},{"i":10,"sec":"第二节 细胞核","title":"核蛋白与亲核蛋白 (p25)","notes":"核蛋白(nuclear protein)/亲核蛋白(karyophilic protein)：细胞质中合成后需要或能够进入细胞核内发挥功能的蛋白质。\n\n【本页英文讲解】\n本页界定核蛋白（nuclear protein）与亲核蛋白（karyophilic protein）。二者指在细胞质中合成后，需要或能够进入细胞核内发挥功能的蛋白质。亲核蛋白这一名称强调其“亲核”特性，即具有被转运进核的能力，通常依赖核定位信号（NLS）。考点：其合成场所为细胞质核糖体，功能场所在核内。","page":25,"level":"掌握","img":"assets/img/ch05/p025.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"什么是核蛋白（亲核蛋白）？","back":"在细胞质中合成后，需要或能够进入细胞核内发挥功能的蛋白质。","mnemonic":"胞质造，核内用","type":"定义","useImg":false,"blank":"细胞质","blank2":"细胞核"}]},{"i":11,"sec":"第二节 细胞核","title":"核定位信号(NLS) (p26)","notes":"核定位序列/核定位信号(nuclear localization sequence/signal, NLS)：亲核蛋白含有的特殊氨基酸序列，引导蛋白入核。通常富含碱性氨基酸(如PKKKRKV)。","page":26,"level":"掌握","img":"assets/img/ch05/p026.jpg","anim":"nls","fig":"核定位序列/信号(NLS)：亲核蛋白特有的氨基酸序列(短片段，4–8 个氨基酸)，保证蛋白能被转运进核。特点：①存在于亲核蛋白内；②一段连续序列(如 SV40 T 抗原 NLS)或分成两段；③不切除，是蛋白永久部分。","points":null,"check":null,"cards":[{"front":"什么是核定位信号(NLS)？其氨基酸组成有何特点？","back":"亲核蛋白含有的特殊氨基酸序列，引导蛋白入核；通常富含碱性氨基酸（如PKKKRKV）。","mnemonic":"碱性序列，入核通行证","type":"定义","useImg":false,"blank":"亲核蛋白","blank2":"碱性氨基酸"}]},{"i":12,"sec":"第二节 细胞核","title":"NLS引导入核 (p28)","notes":"Nuclear-localization signal(NLS) directs proteins to the cell nucleus——NLS引导蛋白进入细胞核。\n\n【本页英文讲解】\n本页说明核定位信号（nuclear-localization signal, NLS）引导蛋白进入细胞核。NLS是蛋白质上的一段特定氨基酸序列，可被输入蛋白（importin）识别，从而介导货物蛋白经核孔复合体入核。NLS通常不被切除，可反复使用。考点：NLS引导入核需与核输出信号（NES）及Ran-GTP调控相联系。","page":28,"level":"掌握","img":"assets/img/ch05/p028.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"NLS的功能是什么？","back":"核定位信号引导蛋白质进入细胞核。","mnemonic":"NLS指路，蛋白入核","type":"功能","useImg":true,"blank":"核定位信号","blank2":"细胞核"}]},{"i":13,"sec":"第二节 细胞核","title":"NLS主动运输 (p29)","notes":"大蛋白进入细胞核需要有核定位信号(NLS)。亲核蛋白通过核孔复合体是一主动运输过程，需消耗能量。","page":29,"level":"掌握","img":"assets/img/ch05/p029.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"大蛋白进入细胞核需要什么条件？该过程有何特点？","back":"需有核定位信号(NLS)；经核孔复合体进行主动运输，需消耗能量。","mnemonic":"大蛋白入核，信号加耗能","type":"流程","useImg":false,"blank":"核定位信号","blank2":"核孔复合体"}]},{"i":14,"sec":"第二节 细胞核","title":"核输出信号(NES) (p30)","notes":"核输出信号(nuclear export signal, NES)：核内物质输出细胞核的信号，帮助核内某些分子通过核孔进入细胞质。通常是富含亮氨酸的序列。","page":30,"level":"掌握","img":"assets/img/ch05/p030.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"核输出信号(NES)的功能是什么？其序列特征如何？","back":"介导核内物质输出细胞核，帮助分子通过核孔进入细胞质；通常为富含亮氨酸的序列","mnemonic":"出核靠亮氨酸","type":"功能","useImg":false,"blank":"核内物质","blank2":"亮氨酸"}]},{"i":15,"sec":"第二节 细胞核","title":"输入蛋白importin (p31)","notes":"亲核蛋白必须与水溶性的NLS受体结合才能穿过核孔复合体，这种受体称importin(输入蛋白)。分布在胞质溶胶中，识别、结合核蛋白的NLS。","page":31,"level":"掌握","img":"assets/img/ch05/p031.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"输入蛋白(importin)是什么？分布在哪里？","back":"亲核蛋白的NLS受体，水溶性；分布在胞质溶胶中，识别并结合核蛋白的NLS","mnemonic":"输入蛋白在胞质，认NLS带进门","type":"定义","useImg":false,"blank":"NLS受体","blank2":"胞质溶胶"}]},{"i":16,"sec":"第二节 细胞核","title":"Ran-GTP的作用 (p32)","notes":"The Ran-GTP(mainly in nucleus) binding causes the receptors to release——Ran-GTP(主要在核内)结合输入蛋白，使其释放货物蛋白。Ran是核质运输的关键调控GTP酶。\n\n【本页英文讲解】\n本页讲Ran-GTP的作用。Ran-GTP（主要在核内）与输入蛋白（importin）结合，使受体释放其运载的货物蛋白（cargo）。Ran是核质运输的关键调控GTP酶（GTPase），其GTP/GDP结合状态在核内外分布不同，驱动货物的装载与释放。考点：Ran-GTP在核内促使货物释放，是核输入循环的核心。","page":32,"level":"掌握","img":"assets/img/ch05/p032.jpg","anim":"ran_cycle","fig":"Ran GTPase 对入核和出核都必需。核内 Ran-GTP 浓度高、胞质 Ran-GDP 高(由 Ran-GEF 和 Ran-GAP 维持)。Ran-GTP 在核内结合入核受体使其释放货物；Ran-GDP 在胞质使出核受体释放货物。图是 Ran 的核质梯度。","points":null,"check":null,"cards":[{"front":"Ran-GTP在核质运输中的作用是什么？","back":"在核内结合输入蛋白，使其释放货物蛋白；Ran是核质运输的关键调控GTP酶","mnemonic":"核内Ran-GTP一到，货物就下车","type":"功能","useImg":false,"blank":"输入蛋白","blank2":"GTP酶"}]},{"i":17,"sec":"第二节 细胞核","title":"入核转运过程 (p34)","notes":"亲核蛋白通过NPC的入核转运：NLS-亲核蛋白→细胞质中受体importin识别并结合形成转运复合物→经NPC入核→核内Ran-GTP结合importin→释放货物→importin回收出核。","page":34,"level":"掌握","img":"assets/img/ch05/p034.jpg","anim":"importin_import","fig":"亲核蛋白经 NPC 的入核转运：NLS-亲核蛋白 + importin 形成转运复合物 → 与 NPC 胞质纤维结合、NPC 构象改变 → 由胞质面转到核质面 → 与 Ran-GTP 结合、复合物解离释放货物 → importin α/β 与 Ran-GTP 返回胞质，Ran-GTP 水解成 Ran-GDP、与 importin 解离。","points":null,"check":{"q":"在亲核蛋白入核转运过程中，细胞质中识别并结合NLS-亲核蛋白的受体是？","o":["A. exportin","B. Ran-GDP","C. importin","D. 核纤层蛋白"],"a":"C","e":"importin在细胞质中识别并结合含NLS的亲核蛋白，形成转运复合物。","oe":["exportin识别核输出信号介导蛋白出核，不结合入核蛋白。","Ran-GDP不直接识别并结合含NLS的亲核蛋白。","importin在细胞质中识别并结合NLS-亲核蛋白，形成转运复合物。","核纤层蛋白是核内结构蛋白，不是入核转运受体。"]},"cards":[{"front":"亲核蛋白经NPC入核转运的主要步骤是什么？","back":"NLS-亲核蛋白与胞质importin结合成转运复合物；经NPC入核；核内Ran-GTP结合importin释放货物；importin回收出核","mnemonic":"结合→入核→Ran释放→回收","type":"流程","useImg":true,"blank":"importin","blank2":"Ran-GTP"}]}],"mcq":[{"id":"ch05_mcq_13","mod":"模块二：核孔运输","modI":1,"q":"核孔复合体(NPC)的结构包括？","o":["A. 胞质环、核篮结构","B. 仅一个孔","C. 双层膜","D. 网格蛋白"],"a":"A","e":"NPC纵向结构：胞质环(外环，8条短纤毛)、核质面的核篮结构，具八重对称。","kp":"ch05_s1_2","oe":["正确。NPC含胞质环与核篮结构，整体呈八重对称。","错误。NPC结构复杂，并非只是一个简单的孔。","错误。双层膜指核被膜本身，不是核孔复合体的结构。","错误。网格蛋白参与膜泡包被，不是NPC的组成成分。"]},{"id":"ch05_mcq_14","mod":"模块二：核孔运输","modI":1,"q":"亲核蛋白入核运输属于？","o":["A. 被动扩散","B. 主动运输(需能量)","C. 自由扩散","D. 胞吞"],"a":"B","e":"大蛋白经NPC入核是主动运输过程，需NLS、importin和Ran-GTP，消耗能量。","kp":"ch05_s1_10","oe":["错误。亲核蛋白入核需NLS和Ran并耗能，不属被动扩散。","正确。入核需NLS、importin与Ran-GTP，消耗能量。","错误。自由扩散针对小分子，大蛋白入核需主动运输。","错误。入核经NPC转运，并不是胞吞途径。"]},{"id":"ch05_mcq_15","mod":"模块二：核孔运输","modI":1,"q":"线粒体蛋白运输的特点不包括？","o":["A. 翻译后转移","B. 需N端导肽","C. 需解折叠","D. 需保持折叠状态"],"a":"D","e":"线粒体蛋白必须解折叠(Hsp70帮助)才能导入，而非保持折叠。","kp":"ch05_s1_6","oe":["错误。线粒体蛋白确为翻译后转移，属其特点，故非本题所问。","错误。线粒体蛋白运输确需N端导肽引导，属其特点。","错误。前体确需Hsp70帮助解折叠，属其特点。","正确。线粒体蛋白必须解折叠才能导入，而非保持折叠状态。"]},{"id":"ch05_mcq_16","mod":"模块二：核孔运输","modI":1,"q":"核输出信号(NES)通常是？","o":["A. 富含亮氨酸的序列","B. 富含赖氨酸的序列","C. KDEL","D. M6P"],"a":"A","e":"NES通常是富含亮氨酸的序列，帮助核内分子输出到细胞质。NLS通常富含碱性氨基酸。","kp":"ch05_s1_14","oe":["正确。NES通常是富含亮氨酸的序列，介导蛋白输出到细胞质。","错误。富含赖氨酸的碱性序列多为NLS，而非NES。","错误。KDEL是内质网驻留信号，不是核输出信号。","错误。M6P是溶酶体酶的分选信号，与核输出无关。"]},{"id":"ch05_mcq_17","mod":"模块二：核孔运输","modI":1,"q":"Ran-GTP在核质运输中的作用是？","o":["A. 结合importin使其释放货物","B. 组装网格蛋白","C. 水解脂类","D. 合成蛋白"],"a":"A","e":"Ran-GTP(主要在核内)结合importin，使其释放货物蛋白，实现核内定向释放。","kp":"ch05_s1_16","oe":["正确。核内Ran-GTP结合importin，促使其释放货物蛋白。","错误。组装网格蛋白与膜泡包被有关，非Ran的功能。","错误。Ran是一种GTP酶，不催化脂类的水解。","错误。Ran不参与蛋白质的合成过程。"]},{"id":"ch05_mcq_18","mod":"模块二：核孔运输","modI":1,"q":"叶绿体基质中的Rubisco小亚基由？","o":["A. 核基因编码,翻译后转运","B. 叶绿体基因编码","C. 线粒体基因编码","D. 无基因编码"],"a":"A","e":"Rubisco的8个小亚基由核基因编码，在胞质合成后翻译后转运入叶绿体基质；大亚基由叶绿体基因编码。","kp":"ch05_s1_0","oe":["正确。小亚基由核基因编码，胞质合成后转运入叶绿体基质。","错误。叶绿体基因编码的是Rubisco的大亚基。","错误。线粒体基因并不编码Rubisco的组分。","错误。小亚基有基因编码，并非无基因编码。"]},{"id":"ch05_mcq_19","mod":"模块二：核孔运输","modI":1,"q":"过氧化物酶体蛋白的引导信号是？","o":["A. PTS1/PTS2","B. NLS","C. KDEL","D. M6P"],"a":"A","e":"过氧化物酶体蛋白经PTS1(多数,C端SKL)/PTS2信号被导入。其发生有两种途径：ER出芽从头形成、已有酶体分裂。","kp":"ch05_s1_11","oe":["正确。PTS1(多为C端SKL)和PTS2引导蛋白进入过氧化物酶体。","错误。NLS导向细胞核，不是过氧化物酶体的引导信号。","错误。KDEL是内质网驻留信号，与过氧化物酶体无关。","错误。M6P导向溶酶体酶的分选，非过氧化物酶体。"]},{"id":"ch05_mcq_20","mod":"模块二：核孔运输","modI":1,"q":"下列属于翻译后转移的蛋白是？","o":["A. 分泌蛋白","B. 线粒体基质蛋白","C. 溶酶体酶","D. 质膜受体"],"a":"B","e":"线粒体、叶绿体、过氧化物酶体蛋白是翻译后转移；分泌蛋白、溶酶体酶、质膜蛋白经ER共翻译转移。","kp":"ch05_s1_10","oe":["错误。分泌蛋白经内质网共翻译转运，不属翻译后转移。","正确。线粒体基质蛋白在胞质合成后，翻译后转运入线粒体。","错误。溶酶体酶经内质网共翻译转运再分选，非翻译后转移。","错误。质膜受体经内质网共翻译转运后运至质膜。"]}],"judge":[{"id":"ch05_judge_4","modI":1,"q":"核孔复合体(NPC)通道直径约9-10nm，约40~60kDa以下的小分子可自由扩散出入。","a":"对","e":"NPC通道直径约9-10nm，40~60kDa以下小分子可自由扩散；大分子经NLS/NES主动运输。","kp":"ch05_s1_2","oe":["核孔复合体通道直径约9-10nm，40~60kDa以下小分子可自由扩散出入。","误记核孔通道直径或可自由扩散的分子量阈值，故判错。"]},{"id":"ch05_judge_5","modI":1,"q":"引导蛋白质进入细胞核的信号是NES，引导出核的信号是NLS。","a":"错","e":"入核信号是NLS(核定位信号)，出核信号是NES(核输出信号)。","kp":"ch05_s1_12","oe":["若以为入核信号是NES、出核信号是NLS则判对，把二者名称记反。","入核信号是NLS(核定位信号)，出核信号是NES(核输出信号)，不可混淆。"]},{"id":"ch05_judge_6","modI":1,"q":"亲核蛋白通过核孔复合体是主动运输过程，需消耗能量。","a":"对","e":"大分子经NPC入核是主动运输，需NLS、importin和Ran-GTP，消耗能量。","kp":"ch05_s1_13","oe":["亲核蛋白入核需NLS、importin和Ran-GTP参与，属主动运输并消耗能量。","若判为错，多误认为入核靠自由扩散，实则依赖载体并水解GTP供能。"]},{"id":"ch05_judge_7","modI":1,"q":"调控核质运输的关键GTP酶是Ran。","a":"对","e":"Ran是核质运输的关键GTP酶；Ran-GTP(核内)结合importin使其释放货物。","kp":"ch05_s1_16","oe":["Ran是核质运输的关键GTP酶，核内Ran-GTP结合importin使货物释放。","若判为错，多因混淆其他GTP酶，实则调控核质运输的关键酶就是Ran。"]}],"fill":[{"id":"ch05_fill_4","modI":1,"q":"核孔复合体(NPC)通道直径约________nm,约________kDa以下小分子可自由扩散出入。","a":"8-10,40","kp":"ch05_s1_2","oe":["核孔复合体通道直径约8-10nm，允许小分子被动扩散出入。","约40kDa以下的小分子可自由扩散通过核孔，故填40。"]},{"id":"ch05_fill_5","modI":1,"q":"引导蛋白入核的信号是________,引导出核的信号是________。","a":"NLS(核定位信号),NES(核输出信号)","kp":"ch05_s1_11","oe":["NLS是引导亲核蛋白入核的短肽信号，故第一空填NLS。","NES是引导蛋白出核的信号，通常富含亮氨酸，故填NES。"]},{"id":"ch05_fill_6","modI":1,"q":"识别NLS的胞质受体是________；调控核质运输的关键GTP酶是________。","a":"importin(输入蛋白),Ran","kp":"ch05_s1_16","oe":["胞质输入蛋白importin识别NLS并携带货物蛋白入核。","Ran是调控核质运输的关键小G蛋白(GTP酶)，故填Ran。"]},{"id":"ch05_fill_9","modI":1,"q":"亲核蛋白通过核孔复合体是________运输过程,需消耗________。","a":"主动,能量","kp":"ch05_s1_13","oe":["亲核蛋白经核孔复合体是主动、选择性的运输过程，故填主动。","该运输依赖Ran-GTP水解供能，故需消耗能量，填能量。"]},{"id":"ch05_fill_10","modI":1,"q":"NPC的纵向结构包括胞质面的________环和核质面的________结构。","a":"胞质(外),核篮","kp":"ch05_s1_4","oe":["NPC胞质面有胞质环，并伸出胞质纤维，故第一空填胞质环。","NPC核质面有核篮状结构，故第二空填核篮。"]},{"id":"ch05_fill_12","modI":1,"q":"亲核蛋白入核时,核内Ran-________结合importin,使其________货物蛋白。","a":"GTP,释放","kp":"ch05_s1_15","oe":["核内Ran与GTP结合成Ran-GTP，与importin结合致货物释放。","Ran-GTP结合importin使其构象改变，从而释放货物蛋白。"]}],"short":[{"id":"ch05_short_2","modI":1,"q":"简述核孔复合体的结构及核质运输机制。","a":"核孔复合体(NPC)及核质运输：\n\n【结构】\n①所有真核细胞间期核普遍存在；\n②通道直径9-10nm，外径约120nm；\n③八重对称：胞质环(外环，8条短纤毛)、核质面的核篮结构。\n\n【运输功能(双功能)】\n①被动运输：离子、小分子代谢产物、40~60kDa以下小分子自由扩散出入；\n②主动运输：大分子经NLS/NES转运。\n\n【入核机制】\n①亲核蛋白含核定位信号(NLS，富含碱性氨基酸)；\n②胞质中importin(输入蛋白)识别并结合NLS，形成转运复合物；\n③经NPC入核；\n④核内Ran-GTP结合importin，释放货物蛋白；\n⑤importin回收出核。\n\n【出核机制】\n①货物含核输出信号(NES，富含亮氨酸)；\n②exportin识别NES，经NPC出核。\n\n【意义】\n实现核质双向物质交换，是基因表达调控的基础。","kp":"ch05_s1_2"},{"id":"ch05_short_4","modI":1,"q":"简述亲核蛋白入核转运的分子机制。","a":"亲核蛋白入核转运机制：\n\n【关键分子】\n①核定位信号(NLS)：亲核蛋白含有的特殊氨基酸序列，通常富含碱性氨基酸(如PKKKRKV)；\n②importin(输入蛋白)：胞质中的NLS受体；\n③Ran：核质运输的关键GTP酶。\n\n【过程】\n①NLS-亲核蛋白在细胞质中与importin识别并结合，形成转运复合物；\n②转运复合物经核孔复合体(NPC)进入细胞核；\n③核内Ran-GTP结合importin，使其构象改变，释放货物蛋白；\n④importin-Ran-GTP复合物返回细胞质，Ran水解GTP，importin循环使用。\n\n【特点】\n①主动运输，消耗能量；\n②方向性由Ran-GTP的核内浓度梯度决定。\n\n【对照出核】\n核输出信号(NES)+exportin介导出核。\n\n【意义】\n是基因表达调控、细胞周期等的基础。","kp":"ch05_s1_17"}],"calc":[{"id":"ch05_calc_2","modI":1,"q":"论述细胞核与细胞质之间物质运输的机制及意义。","a":"核质运输通过核孔复合体实现,由NLS/NES和Ran-GTP精密调控","steps":"【结构基础】\n核孔复合体(NPC)：通道直径9-10nm，外径约120nm，八重对称(胞质环+核篮)，间期核普遍存在。\n\n【运输类型】\n①被动运输：40~60kDa以下小分子自由扩散；\n②主动运输：大分子经NLS/NES。\n\n【入核机制】\n①亲核蛋白含NLS(富含碱性氨基酸)；\n②胞质importin识别结合NLS；\n③经NPC入核；\n④核内Ran-GTP结合importin释放货物。\n\n【出核机制】\n①货物含NES(富含亮氨酸)；\n②exportin识别NES，经NPC出核。\n\n【方向性】\nRan-GTP在核内浓度高、胞质低→决定运输方向。\n\n【意义】\n①实现核质物质交换(蛋白、RNA)；\n②是基因表达调控的基础(转录因子入核)；\n③参与细胞周期、信号转导、病毒感染等；\n④核质运输异常与疾病相关。","kp":"ch05_s1_6"}],"term":[{"id":"ch05_term_3","modI":1,"term":"核孔复合体(NPC)","def":"①真核细胞间期核膜上介导核质物质交换的通道复合体（定义）。②结构：通道直径9-10nm，外径约120nm，八重对称(胞质环+核篮)（结构）。③功能：双功能——被动运输(40~60kDa以下小分子)、主动运输(NLS/NES大分子)（功能）。","kps":"踩分点:①定义(1分)②结构(1分)③双功能(2分)","kp":"ch05_s1_2"},{"id":"ch05_term_4","modI":1,"term":"核定位信号(NLS)","def":"①亲核蛋白含有的、引导其进入细胞核的特殊氨基酸序列（定义）。②特点：通常富含碱性氨基酸(如PKKKRKV)（特点）。③机制：被胞质importin识别结合，经NPC入核（机制）。","kps":"踩分点:①定义(1分)②富含碱性氨基酸(1分)③机制(1分)","kp":"ch05_s1_11"},{"id":"ch05_term_5","modI":1,"term":"核输出信号(NES)","def":"①核内物质输出细胞核的信号序列（定义）。②特点：通常富含亮氨酸（特点）。③机制：被exportin识别，经核孔出核（机制）。","kps":"踩分点:①定义(1分)②富含亮氨酸(1分)③机制(1分)","kp":"ch05_s1_14"},{"id":"ch05_term_6","modI":1,"term":"输入蛋白(Importin)","def":"①胞质溶胶中的NLS受体（定义）。②功能：识别并结合亲核蛋白的NLS，形成转运复合物，经NPC入核（功能）。③调控：核内Ran-GTP结合importin使其释放货物（调控）。","kps":"踩分点:①定义(1分)②功能(1分)③Ran-GTP调控(1分)","kp":"ch05_s1_15"},{"id":"ch05_term_7","modI":1,"term":"Ran蛋白","def":"①核质运输的关键GTP酶（定义）。②功能：Ran-GTP(主要在核内)结合importin使其释放货物蛋白，决定运输方向（功能）。③意义：Ran-GTP的核内浓度梯度是核质运输方向性的基础（意义）。","kps":"踩分点:①定义(1分)②功能(2分)③意义(1分)","kp":"ch05_s1_16"},{"id":"ch05_term_12","modI":1,"term":"核篮结构","def":"①核孔复合体核质面一侧的篮状结构（定义）。②组成：由8条纤丝汇聚成环（组成）。③功能：参与核质物质运输（功能）。","kps":"踩分点:①定义(1分)②组成(1分)③功能(1分)","kp":"ch05_s1_5"}]},{"i":2,"name":"模块三：过氧化物酶体","slides":[{"i":0,"sec":"第三节 过氧化物酶体","title":"过氧化物酶体 (p35)","notes":"过氧化物酶体(peroxisome)：单层膜围绕成的细胞器，又称微体(microbody)。含多种氧化酶和过氧化氢酶。鼠肝细胞超薄切片显示过氧化物酶体和线粒体。","page":35,"level":"掌握","img":"assets/img/ch05/p035.jpg","anim":null,"fig":"过氧化物酶体(peroxisome)：单层膜围绕的细胞器，又称微体。含多种氧化酶和过氧化氢酶，能分解脂肪酸、解毒。图中鼠肝细胞超薄切片显示过氧化物酶体(圆形小体)和线粒体。","points":null,"check":null,"cards":[{"front":"过氧化物酶体的结构特点和主要酶是什么？","back":"单层膜围绕的细胞器，又称微体；含多种氧化酶和过氧化氢酶","mnemonic":"单层膜微体，氧化酶+过氧化氢酶","type":"组成","useImg":true,"blank":"过氧化氢酶","blank2":"氧化酶"}]},{"i":1,"sec":"第三节 过氧化物酶体","title":"过氧化物酶体的发生 (p37)","notes":"过氧化物酶体的生物发生与分裂：蛋白质主要在细胞质基质游离核糖体合成，但有两种发生途径：①过氧化物酶体的一些膜蛋白Pex3/Pex16来自内质网；②新过氧化物酶体形成。","page":37,"level":"掌握","img":"assets/img/ch05/p037.jpg","anim":"peroxisome","fig":"过氧化物酶体的生物发生：蛋白质在胞质游离核糖体合成，有两种发生途径——①一些膜蛋白(Pex3/Pex16)来自内质网；②由已有过氧化物酶体分裂。图给出两种途径的模型。","points":null,"check":null,"cards":[{"front":"过氧化物酶体蛋白在哪里合成？其发生有何特点？","back":"蛋白质主要在细胞质基质游离核糖体合成；发生与分裂相关，部分膜蛋白Pex3/Pex16来自内质网","mnemonic":"游离核糖体造蛋白，ER供膜","type":"流程","useImg":false,"blank":"细胞质基质游离核糖体","blank2":"内质网"}]},{"i":2,"sec":"第三节 过氧化物酶体","title":"两种形成途径 (p38)","notes":"新过氧化物酶体形成的两种途径：①从头形成(由ER出芽)；②由已有过氧化物酶体分裂。过氧化物酶体蛋白经PTS信号(PTS1/PTS2)被导入。","page":38,"level":"掌握","img":"assets/img/ch05/p038.jpg","anim":null,"fig":"新过氧化物酶体形成的两种途径：①从头形成(由 ER 出芽)；②由已有过氧化物酶体分裂。过氧化物酶体蛋白经 PTS 信号(PTS1 多数为 C 端 SKL，PTS2 为 N 端)被导入。图对比两条途径。","points":null,"check":null,"cards":[{"front":"新过氧化物酶体形成的两种途径是什么？蛋白靠什么信号导入？","back":"①从头形成(由ER出芽)；②由已有过氧化物酶体分裂；蛋白经PTS1/PTS2信号导入","mnemonic":"从头出芽或分裂，PTS指路","type":"流程","useImg":false,"blank":"PTS1/PTS2信号","blank2":"过氧化物酶体分裂"}]}],"mcq":[{"id":"ch05_mcq_21","mod":"模块三：过氧化物酶体","modI":2,"q":"NPC被动运输的分子量上限约为？","o":["A. 40~60kDa","B. 100kDa","C. 10kDa","D. 500kDa"],"a":"A","e":"约40~60kDa以下的小分子物质可自由扩散出入细胞核(原则上，但许多小分子例外)。","kp":null,"oe":["正确。约40~60kDa以下小分子可经NPC自由扩散出入细胞核。","错误。100kDa的大分子需主动运输，不能自由扩散。","错误。上限约40~60kDa，并非仅为10kDa。","错误。500kDa远超过被动运输的分子量上限。"]},{"id":"ch05_mcq_22","mod":"模块三：过氧化物酶体","modI":2,"q":"线粒体蛋白前体在胞质解折叠需要？","o":["A. Hsp70和ATP","B. 网格蛋白","C. SNARE","D. Ran"],"a":"A","e":"前体蛋白在胞质与Hsp70结合，ATP→ADP，解折叠为松散结构后才能导入线粒体。","kp":"ch05_s2_0","oe":["正确。胞质Hsp70结合前体并水解ATP，使其解折叠成松散结构。","错误。网格蛋白参与膜泡包被，与蛋白解折叠无关。","错误。SNARE介导膜泡融合，不参与前体解折叠。","错误。Ran参与核质运输，不参与线粒体前体的解折叠。"]},{"id":"ch05_mcq_23","mod":"模块三：过氧化物酶体","modI":2,"q":"亲核蛋白的NLS通常富含？","o":["A. 碱性氨基酸(如赖氨酸/精氨酸)","B. 酸性氨基酸","C. 疏水氨基酸","D. 无特定氨基酸"],"a":"A","e":"NLS通常富含碱性氨基酸(如SV40大T抗原的PKKKRKV)，带正电，与importin结合。","kp":"ch05_s2_1","oe":["正确。NLS富含赖氨酸、精氨酸等碱性氨基酸，带正电荷。","错误。酸性氨基酸带负电，与NLS富含碱性氨基酸不符。","错误。疏水氨基酸不构成NLS的序列特征。","错误。NLS有特定氨基酸组成，并非无特定氨基酸。"]},{"id":"ch05_mcq_24","mod":"模块三：过氧化物酶体","modI":2,"q":"核孔复合体存在于？","o":["A. 间期细胞核","B. 分裂期","C. 线粒体","D. 溶酶体"],"a":"A","e":"所有真核细胞(酵母、人)间期细胞核普遍存在NPC，是核质交换通道。","kp":null,"oe":["正确。NPC普遍存在于真核细胞的间期核被膜上。","错误。分裂期核膜解体，NPC消失，非其存在部位。","错误。线粒体上没有核孔复合体。","错误。溶酶体上没有核孔复合体。"]},{"id":"ch05_mcq_25","mod":"模块三：过氧化物酶体","modI":2,"q":"叶绿体蛋白分选不包括？","o":["A. 基质蛋白","B. 类囊体腔蛋白","C. 类囊体膜蛋白","D. 核蛋白"],"a":"D","e":"叶绿体蛋白分选：基质蛋白、类囊体腔蛋白、类囊体膜蛋白。核蛋白经核孔运输，不属叶绿体分选。","kp":"ch05_s2_2","oe":["错误。基质蛋白属叶绿体蛋白分选，故不是本题所问。","错误。类囊体腔蛋白属叶绿体蛋白分选。","错误。类囊体膜蛋白属叶绿体蛋白分选。","正确。核蛋白经核孔运输，不属叶绿体蛋白分选。"]}],"judge":[{"id":"ch05_judge_8","modI":2,"q":"过氧化物酶体的蛋白引导信号是PTS1/PTS2。","a":"对","e":"过氧化物酶体蛋白经PTS1(多数,C端SKL)或PTS2信号被导入。","kp":"ch05_s2_1","oe":["过氧化物酶体蛋白主要经C端PTS1(SKL)或N端PTS2信号被导入。","若判为错，可能误认其靠其他信号，实则PTS1/PTS2是其引导信号。"]},{"id":"ch05_judge_9","modI":2,"q":"过氧化物酶体只有一种发生途径，即由内质网出芽形成。","a":"错","e":"过氧化物酶体有两种发生途径：ER出芽从头形成、已有过氧化物酶体分裂。","kp":"ch05_s2_1","oe":["若判对则误认为仅内质网出芽一种途径，忽略酶体还可分裂发生。","过氧化物酶体有两条发生途径：内质网出芽从头形成与已有酶体分裂。"]}],"fill":[{"id":"ch05_fill_7","modI":2,"q":"过氧化物酶体又称________,其蛋白引导信号是________,发生有ER出芽和________两种途径。","a":"微体(microbody),PTS1/PTS2,已有酶体分裂","kp":"ch05_s2_1","oe":["过氧化物酶体因体积小又称微体，含氧化酶和过氧化氢酶。","过氧化物酶体蛋白的引导信号为PTS1或PTS2，故为答案。","过氧化物酶体可由ER出芽生成，也可由已有酶体分裂产生。"]}],"short":[{"id":"ch05_short_6","modI":2,"q":"简述过氧化物酶体的发生及蛋白导入。","a":"过氧化物酶体的发生及蛋白导入：\n\n【结构】\n单层膜围绕的细胞器，又称微体(microbody)，含氧化酶和过氧化氢酶。\n\n【蛋白合成】\n过氧化物酶体蛋白主要在细胞质基质游离核糖体合成。\n\n【两种发生途径】\n①从头形成：过氧化物酶体的一些膜蛋白Pex3/Pex16来自内质网，由ER出芽形成新的过氧化物酶体；\n②分裂：由已有过氧化物酶体分裂产生。\n\n【蛋白导入】\n①经PTS1(多数蛋白，C端SKL序列)或PTS2(少数)信号；\n②由Pex蛋白(受体)识别；\n③可折叠状态即可导入(与线粒体需解折叠不同)。\n\n【意义】\n保证过氧化物酶体的生物发生和功能(脂肪酸氧化、过氧化氢分解)。","kp":"ch05_s2_1"}],"calc":[],"term":[{"id":"ch05_term_9","modI":2,"term":"过氧化物酶体(Peroxisome)","def":"①单层膜围绕的细胞器，又称微体(microbody)（定义）。②组成：含氧化酶和过氧化氢酶（组成）。③发生：两种途径——ER出芽从头形成、已有酶体分裂（发生）。④蛋白导入：经PTS1/PTS2信号（导入）。","kps":"踩分点:①定义(1分)②组成(1分)③发生(1分)④PTS信号(1分)","kp":"ch05_s2_0"},{"id":"ch05_term_13","modI":2,"term":"PTS信号","def":"①过氧化物酶体蛋白的靶向信号(PTS1/PTS2)（定义）。②PTS1：多数过氧化物酶体蛋白，C端SKL序列；PTS2：少数蛋白，N端（分类）。③功能：由Pex蛋白受体识别，引导蛋白导入过氧化物酶体（功能）。","kps":"踩分点:①定义(1分)②PTS1/PTS2(2分)③功能(1分)","kp":"ch05_s2_2"}]}],"mcq":[{"id":"ch05_mcq_1","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体蛋白N端的引导序列称为？","o":["A. 信号肽","B. 导肽(presequence)","C. 转运肽","D. 前导序列"],"a":"B","e":"线粒体蛋白N端为导肽(presequence)；叶绿体蛋白N端为转运肽(transit peptide)。两者都是翻译后转移的引导信号。","kp":"ch05_s0_2","oe":["信号肽通常指引导分泌蛋白进入内质网的序列，非线粒体。","线粒体蛋白N端的引导序列称为导肽（presequence）。","转运肽指叶绿体蛋白N端的引导序列，非线粒体。","前导序列是泛指名称，线粒体引导序列标准称导肽。"]},{"id":"ch05_mcq_2","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体蛋白前体进入基质需要？","o":["A. 保持折叠状态","B. 由Hsp70帮助解折叠","C. 直接穿过膜","D. 经核孔"],"a":"B","e":"Only unfolded proteins can be imported——前体蛋白在胞质与Hsp70结合，ATP水解后解折叠，才能经TOM/TIM进入线粒体。","kp":"ch05_s0_2","oe":["错误。前体必须解折叠才可被导入，保持折叠无法通过TOM/TIM。","正确。胞质Hsp70结合前体并水解ATP，使其解折叠后经TOM/TIM进入基质。","错误。需借助TOM/TIM转运复合体，不能直接穿过线粒体膜。","错误。核孔是核质运输通道，线粒体蛋白不经核孔进入基质。"]},{"id":"ch05_mcq_3","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体蛋白前体跨膜转运发生在？","o":["A. 任意膜位置","B. 内外膜接触点","C. 核孔","D. 高尔基体"],"a":"B","e":"前体蛋白到线粒体基质的转移只发生在少数线粒体内外膜相'接触点'，经TOM(外膜)和TIM(内膜)复合体。","kp":"ch05_s0_2","oe":["错误。并非任意膜位置，只在少数内外膜接触点进行转运。","正确。前体经内外膜接触点的TOM与TIM复合体转运进入基质。","错误。核孔介导核质运输，与线粒体蛋白跨膜转运无关。","错误。高尔基体参与膜泡运输，不参与线粒体蛋白导入。"]},{"id":"ch05_mcq_4","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"叶绿体蛋白N端的引导序列称为？","o":["A. 导肽","B. 转运肽(transit peptide)","C. 信号肽","D. NLS"],"a":"B","e":"叶绿体前体蛋白N端含转运肽(transit peptide)，引导入叶绿体后被切除。","kp":"ch05_s0_8","oe":["错误。导肽多指线粒体蛋白引导序列，叶绿体特称转运肽。","正确。叶绿体前体蛋白N端为转运肽，引导入叶绿体后被切除。","错误。信号肽引导蛋白进入内质网，属共翻译转运。","错误。NLS是核定位信号，负责引导蛋白进入细胞核。"]},{"id":"ch05_mcq_5","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"类囊体腔蛋白的转运肽特点是？","o":["A. 只有一段","B. 分2个区(导向基质+导向类囊体腔)","C. 无引导功能","D. 位于C端"],"a":"B","e":"类囊体腔蛋白的转运肽分2区：N端导向叶绿体基质序列，接下来是导向类囊体腔的序列，分两步引导。","kp":"ch05_s0_10","oe":["错误。并非只有一段，而是分导向基质与类囊体腔两个区。","正确。转运肽分两区，先导向叶绿体基质，再导向类囊体腔。","错误。转运肽具有引导功能，可定向运输蛋白至类囊体腔。","错误。转运肽位于蛋白N端，而不是C端。"]},{"id":"ch05_mcq_6","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"核孔复合体(NPC)的直径(通道)约为？","o":["A. 9-10nm","B. 120nm","C. 1nm","D. 50nm"],"a":"A","e":"NPC通道直径约9-10nm，外径约120nm；40~60kDa以下小分子可自由扩散。","kp":"ch05_s0_4","oe":["正确。NPC通道直径约9-10nm，小分子物质可自由扩散通过。","错误。120nm是核孔复合体的外径，不是其通道直径。","错误。1nm过小，远小于实际通道，多数分子无法通过。","错误。50nm大于实际通道直径，与事实不符。"]},{"id":"ch05_mcq_7","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"引导蛋白质进入细胞核的信号是？","o":["A. NLS(核定位信号)","B. NES","C. KDEL","D. M6P"],"a":"A","e":"NLS(核定位信号)引导亲核蛋白入核；NES(核输出信号)介导出核；KDEL是ER驻留信号；M6P是溶酶体信号。","kp":"ch05_s0_8","oe":["正确。NLS核定位信号引导亲核蛋白经NPC进入细胞核。","错误。NES是核输出信号，介导核内蛋白输出到细胞质。","错误。KDEL是内质网驻留信号，使蛋白滞留于内质网。","错误。M6P是溶酶体酶的分选信号，导向溶酶体。"]},{"id":"ch05_mcq_8","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"识别并结合NLS的胞质受体是？","o":["A. importin(输入蛋白)","B. exportin","C. SRP","D. dynamin"],"a":"A","e":"亲核蛋白必须与NLS受体importin结合才能穿过NPC。importin分布在胞质溶胶中。","kp":"ch05_s0_2","oe":["正确。胞质中importin识别并结合NLS，介导货物蛋白入核。","错误。exportin介导含NES的货物蛋白从核内输出。","错误。SRP识别信号肽，介导分泌蛋白的共翻译转运。","错误。dynamin是参与膜泡颈缩的GTP酶，与入核无关。"]},{"id":"ch05_mcq_9","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"调控核质运输的关键GTP酶是？","o":["A. Ran","B. Rab","C. Sar","D. ARF"],"a":"A","e":"Ran是核质运输的关键GTP酶。Ran-GTP(主要在核内)结合importin使其释放货物蛋白。","kp":"ch05_s0_1","oe":["正确。Ran是核质运输的关键GTP酶，Ran-GTP调控货物释放。","错误。Rab调控膜泡运输与融合，不参与核质运输。","错误。Sar参与内质网到高尔基体的膜泡形成。","错误。ARF参与膜泡形成与囊泡运输，非核质运输。"]},{"id":"ch05_mcq_10","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"40~60kDa以下的小分子出入细胞核的方式是？","o":["A. 主动运输","B. 被动扩散(经NPC)","C. 胞吞","D. 跨膜转运"],"a":"B","e":"NPC双功能：离子、小分子代谢产物、40~60kDa以下小分子可自由扩散出入核；大分子经NLS/NES主动运输。","kp":"ch05_s0_0","oe":["错误。小分子经NPC自由扩散，不属消耗能量的主动运输。","正确。40~60kDa以下小分子可经NPC自由扩散出入细胞核。","错误。胞吞是大分子物质入胞方式，并不是入核方式。","错误。经核孔扩散进入，而非跨脂双层膜的跨膜转运。"]},{"id":"ch05_mcq_11","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"线粒体外膜和内膜的蛋白转运子分别是？","o":["A. TOM和TIM","B. TIM和TOM","C. SRP和SR","D. NPC"],"a":"A","e":"外膜转运子TOM复合体、内膜转运子TIM复合体，前体蛋白经TOM进入、经TIM进入基质。","kp":"ch05_s0_4","oe":["正确。外膜转运子为TOM复合体，内膜转运子为TIM复合体。","错误。顺序颠倒，外膜是TOM，内膜是TIM。","错误。SRP与SR参与内质网共翻译转运，与线粒体无关。","错误。NPC是核孔复合体，负责核质之间的运输。"]},{"id":"ch05_mcq_12","mod":"模块一：线粒体与叶绿体蛋白转运","modI":0,"q":"过氧化物酶体的另一种名称是？","o":["A. 微体(microbody)","B. 溶酶体","C. 内体","D. 液泡"],"a":"A","e":"过氧化物酶体又称微体(microbody)，单层膜，含氧化酶和过氧化氢酶。","kp":"ch05_s0_0","oe":["正确。过氧化物酶体又称微体，为单层膜细胞器。","错误。溶酶体含酸性水解酶，与过氧化物酶体不同。","错误。内体参与胞吞物质的分选，不是过氧化物酶体。","错误。液泡是植物细胞的贮水细胞器，另属一类。"]},{"id":"ch05_mcq_13","mod":"模块二：核孔运输","modI":1,"q":"核孔复合体(NPC)的结构包括？","o":["A. 胞质环、核篮结构","B. 仅一个孔","C. 双层膜","D. 网格蛋白"],"a":"A","e":"NPC纵向结构：胞质环(外环，8条短纤毛)、核质面的核篮结构，具八重对称。","kp":"ch05_s1_2","oe":["正确。NPC含胞质环与核篮结构，整体呈八重对称。","错误。NPC结构复杂，并非只是一个简单的孔。","错误。双层膜指核被膜本身，不是核孔复合体的结构。","错误。网格蛋白参与膜泡包被，不是NPC的组成成分。"]},{"id":"ch05_mcq_14","mod":"模块二：核孔运输","modI":1,"q":"亲核蛋白入核运输属于？","o":["A. 被动扩散","B. 主动运输(需能量)","C. 自由扩散","D. 胞吞"],"a":"B","e":"大蛋白经NPC入核是主动运输过程，需NLS、importin和Ran-GTP，消耗能量。","kp":"ch05_s1_10","oe":["错误。亲核蛋白入核需NLS和Ran并耗能，不属被动扩散。","正确。入核需NLS、importin与Ran-GTP，消耗能量。","错误。自由扩散针对小分子，大蛋白入核需主动运输。","错误。入核经NPC转运，并不是胞吞途径。"]},{"id":"ch05_mcq_15","mod":"模块二：核孔运输","modI":1,"q":"线粒体蛋白运输的特点不包括？","o":["A. 翻译后转移","B. 需N端导肽","C. 需解折叠","D. 需保持折叠状态"],"a":"D","e":"线粒体蛋白必须解折叠(Hsp70帮助)才能导入，而非保持折叠。","kp":"ch05_s1_6","oe":["错误。线粒体蛋白确为翻译后转移，属其特点，故非本题所问。","错误。线粒体蛋白运输确需N端导肽引导，属其特点。","错误。前体确需Hsp70帮助解折叠，属其特点。","正确。线粒体蛋白必须解折叠才能导入，而非保持折叠状态。"]},{"id":"ch05_mcq_16","mod":"模块二：核孔运输","modI":1,"q":"核输出信号(NES)通常是？","o":["A. 富含亮氨酸的序列","B. 富含赖氨酸的序列","C. KDEL","D. M6P"],"a":"A","e":"NES通常是富含亮氨酸的序列，帮助核内分子输出到细胞质。NLS通常富含碱性氨基酸。","kp":"ch05_s1_14","oe":["正确。NES通常是富含亮氨酸的序列，介导蛋白输出到细胞质。","错误。富含赖氨酸的碱性序列多为NLS，而非NES。","错误。KDEL是内质网驻留信号，不是核输出信号。","错误。M6P是溶酶体酶的分选信号，与核输出无关。"]},{"id":"ch05_mcq_17","mod":"模块二：核孔运输","modI":1,"q":"Ran-GTP在核质运输中的作用是？","o":["A. 结合importin使其释放货物","B. 组装网格蛋白","C. 水解脂类","D. 合成蛋白"],"a":"A","e":"Ran-GTP(主要在核内)结合importin，使其释放货物蛋白，实现核内定向释放。","kp":"ch05_s1_16","oe":["正确。核内Ran-GTP结合importin，促使其释放货物蛋白。","错误。组装网格蛋白与膜泡包被有关，非Ran的功能。","错误。Ran是一种GTP酶，不催化脂类的水解。","错误。Ran不参与蛋白质的合成过程。"]},{"id":"ch05_mcq_18","mod":"模块二：核孔运输","modI":1,"q":"叶绿体基质中的Rubisco小亚基由？","o":["A. 核基因编码,翻译后转运","B. 叶绿体基因编码","C. 线粒体基因编码","D. 无基因编码"],"a":"A","e":"Rubisco的8个小亚基由核基因编码，在胞质合成后翻译后转运入叶绿体基质；大亚基由叶绿体基因编码。","kp":"ch05_s1_0","oe":["正确。小亚基由核基因编码，胞质合成后转运入叶绿体基质。","错误。叶绿体基因编码的是Rubisco的大亚基。","错误。线粒体基因并不编码Rubisco的组分。","错误。小亚基有基因编码，并非无基因编码。"]},{"id":"ch05_mcq_19","mod":"模块二：核孔运输","modI":1,"q":"过氧化物酶体蛋白的引导信号是？","o":["A. PTS1/PTS2","B. NLS","C. KDEL","D. M6P"],"a":"A","e":"过氧化物酶体蛋白经PTS1(多数,C端SKL)/PTS2信号被导入。其发生有两种途径：ER出芽从头形成、已有酶体分裂。","kp":"ch05_s1_11","oe":["正确。PTS1(多为C端SKL)和PTS2引导蛋白进入过氧化物酶体。","错误。NLS导向细胞核，不是过氧化物酶体的引导信号。","错误。KDEL是内质网驻留信号，与过氧化物酶体无关。","错误。M6P导向溶酶体酶的分选，非过氧化物酶体。"]},{"id":"ch05_mcq_20","mod":"模块二：核孔运输","modI":1,"q":"下列属于翻译后转移的蛋白是？","o":["A. 分泌蛋白","B. 线粒体基质蛋白","C. 溶酶体酶","D. 质膜受体"],"a":"B","e":"线粒体、叶绿体、过氧化物酶体蛋白是翻译后转移；分泌蛋白、溶酶体酶、质膜蛋白经ER共翻译转移。","kp":"ch05_s1_10","oe":["错误。分泌蛋白经内质网共翻译转运，不属翻译后转移。","正确。线粒体基质蛋白在胞质合成后，翻译后转运入线粒体。","错误。溶酶体酶经内质网共翻译转运再分选，非翻译后转移。","错误。质膜受体经内质网共翻译转运后运至质膜。"]},{"id":"ch05_mcq_21","mod":"模块三：过氧化物酶体","modI":2,"q":"NPC被动运输的分子量上限约为？","o":["A. 40~60kDa","B. 100kDa","C. 10kDa","D. 500kDa"],"a":"A","e":"约40~60kDa以下的小分子物质可自由扩散出入细胞核(原则上，但许多小分子例外)。","kp":null,"oe":["正确。约40~60kDa以下小分子可经NPC自由扩散出入细胞核。","错误。100kDa的大分子需主动运输，不能自由扩散。","错误。上限约40~60kDa，并非仅为10kDa。","错误。500kDa远超过被动运输的分子量上限。"]},{"id":"ch05_mcq_22","mod":"模块三：过氧化物酶体","modI":2,"q":"线粒体蛋白前体在胞质解折叠需要？","o":["A. Hsp70和ATP","B. 网格蛋白","C. SNARE","D. Ran"],"a":"A","e":"前体蛋白在胞质与Hsp70结合，ATP→ADP，解折叠为松散结构后才能导入线粒体。","kp":"ch05_s2_0","oe":["正确。胞质Hsp70结合前体并水解ATP，使其解折叠成松散结构。","错误。网格蛋白参与膜泡包被，与蛋白解折叠无关。","错误。SNARE介导膜泡融合，不参与前体解折叠。","错误。Ran参与核质运输，不参与线粒体前体的解折叠。"]},{"id":"ch05_mcq_23","mod":"模块三：过氧化物酶体","modI":2,"q":"亲核蛋白的NLS通常富含？","o":["A. 碱性氨基酸(如赖氨酸/精氨酸)","B. 酸性氨基酸","C. 疏水氨基酸","D. 无特定氨基酸"],"a":"A","e":"NLS通常富含碱性氨基酸(如SV40大T抗原的PKKKRKV)，带正电，与importin结合。","kp":"ch05_s2_1","oe":["正确。NLS富含赖氨酸、精氨酸等碱性氨基酸，带正电荷。","错误。酸性氨基酸带负电，与NLS富含碱性氨基酸不符。","错误。疏水氨基酸不构成NLS的序列特征。","错误。NLS有特定氨基酸组成，并非无特定氨基酸。"]},{"id":"ch05_mcq_24","mod":"模块三：过氧化物酶体","modI":2,"q":"核孔复合体存在于？","o":["A. 间期细胞核","B. 分裂期","C. 线粒体","D. 溶酶体"],"a":"A","e":"所有真核细胞(酵母、人)间期细胞核普遍存在NPC，是核质交换通道。","kp":null,"oe":["正确。NPC普遍存在于真核细胞的间期核被膜上。","错误。分裂期核膜解体，NPC消失，非其存在部位。","错误。线粒体上没有核孔复合体。","错误。溶酶体上没有核孔复合体。"]},{"id":"ch05_mcq_25","mod":"模块三：过氧化物酶体","modI":2,"q":"叶绿体蛋白分选不包括？","o":["A. 基质蛋白","B. 类囊体腔蛋白","C. 类囊体膜蛋白","D. 核蛋白"],"a":"D","e":"叶绿体蛋白分选：基质蛋白、类囊体腔蛋白、类囊体膜蛋白。核蛋白经核孔运输，不属叶绿体分选。","kp":"ch05_s2_2","oe":["错误。基质蛋白属叶绿体蛋白分选，故不是本题所问。","错误。类囊体腔蛋白属叶绿体蛋白分选。","错误。类囊体膜蛋白属叶绿体蛋白分选。","正确。核蛋白经核孔运输，不属叶绿体蛋白分选。"]}],"judge":[{"id":"ch05_judge_1","modI":0,"q":"线粒体蛋白N端含导肽，叶绿体蛋白N端含转运肽。","a":"对","e":"线粒体蛋白N端为导肽(presequence)，叶绿体蛋白N端为转运肽(transit peptide)。","kp":"ch05_s0_8","oe":["线粒体蛋白N端为导肽，叶绿体蛋白N端为转运肽。","误把线粒体与叶绿体的N端信号名称互换，故判错。"]},{"id":"ch05_judge_2","modI":0,"q":"线粒体蛋白前体必须解折叠后才能被导入线粒体。","a":"对","e":"只有解折叠的蛋白能进入线粒体；前体蛋白在胞质由Hsp70帮助、消耗ATP解折叠。","kp":"ch05_s0_7","oe":["只有解折叠的蛋白能进入线粒体，前体蛋白在胞质由Hsp70耗能解折叠。","误以为折叠态蛋白可直接导入或无需分子伴侣，故判错。"]},{"id":"ch05_judge_3","modI":0,"q":"线粒体外膜和内膜的蛋白转运子分别是TOM和TIM复合体。","a":"对","e":"外膜为TOM复合体、内膜为TIM复合体，前体蛋白经二者进入基质。","kp":"ch05_s0_4","oe":["线粒体外膜为TOM复合体、内膜为TIM复合体，前体蛋白经二者进入基质。","误把TOM与TIM对应的膜或内外顺序记反，故判错。"]},{"id":"ch05_judge_4","modI":1,"q":"核孔复合体(NPC)通道直径约9-10nm，约40~60kDa以下的小分子可自由扩散出入。","a":"对","e":"NPC通道直径约9-10nm，40~60kDa以下小分子可自由扩散；大分子经NLS/NES主动运输。","kp":"ch05_s1_2","oe":["核孔复合体通道直径约9-10nm，40~60kDa以下小分子可自由扩散出入。","误记核孔通道直径或可自由扩散的分子量阈值，故判错。"]},{"id":"ch05_judge_5","modI":1,"q":"引导蛋白质进入细胞核的信号是NES，引导出核的信号是NLS。","a":"错","e":"入核信号是NLS(核定位信号)，出核信号是NES(核输出信号)。","kp":"ch05_s1_12","oe":["若以为入核信号是NES、出核信号是NLS则判对，把二者名称记反。","入核信号是NLS(核定位信号)，出核信号是NES(核输出信号)，不可混淆。"]},{"id":"ch05_judge_6","modI":1,"q":"亲核蛋白通过核孔复合体是主动运输过程，需消耗能量。","a":"对","e":"大分子经NPC入核是主动运输，需NLS、importin和Ran-GTP，消耗能量。","kp":"ch05_s1_13","oe":["亲核蛋白入核需NLS、importin和Ran-GTP参与，属主动运输并消耗能量。","若判为错，多误认为入核靠自由扩散，实则依赖载体并水解GTP供能。"]},{"id":"ch05_judge_7","modI":1,"q":"调控核质运输的关键GTP酶是Ran。","a":"对","e":"Ran是核质运输的关键GTP酶；Ran-GTP(核内)结合importin使其释放货物。","kp":"ch05_s1_16","oe":["Ran是核质运输的关键GTP酶，核内Ran-GTP结合importin使货物释放。","若判为错，多因混淆其他GTP酶，实则调控核质运输的关键酶就是Ran。"]},{"id":"ch05_judge_8","modI":2,"q":"过氧化物酶体的蛋白引导信号是PTS1/PTS2。","a":"对","e":"过氧化物酶体蛋白经PTS1(多数,C端SKL)或PTS2信号被导入。","kp":"ch05_s2_1","oe":["过氧化物酶体蛋白主要经C端PTS1(SKL)或N端PTS2信号被导入。","若判为错，可能误认其靠其他信号，实则PTS1/PTS2是其引导信号。"]},{"id":"ch05_judge_9","modI":2,"q":"过氧化物酶体只有一种发生途径，即由内质网出芽形成。","a":"错","e":"过氧化物酶体有两种发生途径：ER出芽从头形成、已有过氧化物酶体分裂。","kp":"ch05_s2_1","oe":["若判对则误认为仅内质网出芽一种途径，忽略酶体还可分裂发生。","过氧化物酶体有两条发生途径：内质网出芽从头形成与已有酶体分裂。"]},{"id":"ch05_judge_10","modI":0,"q":"叶绿体类囊体腔蛋白的转运肽可分为导向基质和导向类囊体腔两个区。","a":"对","e":"类囊体腔蛋白转运肽分2区：N端导向基质序列+导向类囊体腔序列，分两步引导。","kp":"ch05_s0_10","oe":["类囊体腔蛋白转运肽分N端导向基质区与导向类囊体腔区，分两步引导。","误判为错者多不知转运肽可分导向基质和类囊体腔两个功能区。"]}],"fill":[{"id":"ch05_fill_1","modI":0,"q":"线粒体蛋白N端含________,叶绿体蛋白N端含________,两者都引导翻译后转移。","a":"导肽(presequence),转运肽(transit peptide)","kp":"ch05_s0_8","oe":["线粒体蛋白前体N端的导肽引导其翻译后转运入线粒体。","叶绿体蛋白N端的转运肽引导其翻译后转运入叶绿体。"]},{"id":"ch05_fill_2","modI":0,"q":"线粒体蛋白前体在胞质由________帮助、消耗________解折叠后才能导入。","a":"Hsp70,ATP","kp":"ch05_s0_7","oe":["胞质Hsp70分子伴侣使前体解折叠并保持可转运状态。","前体解折叠由Hsp70消耗ATP驱动，导入过程也需ATP。"]},{"id":"ch05_fill_3","modI":0,"q":"线粒体外膜转运子为________复合体,内膜为________复合体,前体在内外膜________点转运。","a":"TOM,TIM,接触","kp":"ch05_s0_4","oe":["线粒体外膜转运子为TOM复合体，识别并导入前体蛋白。","线粒体内膜转运子为TIM复合体，将前体送入基质。","前体在内外膜相互接触的接触点处协调转运，故填接触点。"]},{"id":"ch05_fill_4","modI":1,"q":"核孔复合体(NPC)通道直径约________nm,约________kDa以下小分子可自由扩散出入。","a":"8-10,40","kp":"ch05_s1_2","oe":["核孔复合体通道直径约8-10nm，允许小分子被动扩散出入。","约40kDa以下的小分子可自由扩散通过核孔，故填40。"]},{"id":"ch05_fill_5","modI":1,"q":"引导蛋白入核的信号是________,引导出核的信号是________。","a":"NLS(核定位信号),NES(核输出信号)","kp":"ch05_s1_11","oe":["NLS是引导亲核蛋白入核的短肽信号，故第一空填NLS。","NES是引导蛋白出核的信号，通常富含亮氨酸，故填NES。"]},{"id":"ch05_fill_6","modI":1,"q":"识别NLS的胞质受体是________；调控核质运输的关键GTP酶是________。","a":"importin(输入蛋白),Ran","kp":"ch05_s1_16","oe":["胞质输入蛋白importin识别NLS并携带货物蛋白入核。","Ran是调控核质运输的关键小G蛋白(GTP酶)，故填Ran。"]},{"id":"ch05_fill_7","modI":2,"q":"过氧化物酶体又称________,其蛋白引导信号是________,发生有ER出芽和________两种途径。","a":"微体(microbody),PTS1/PTS2,已有酶体分裂","kp":"ch05_s2_1","oe":["过氧化物酶体因体积小又称微体，含氧化酶和过氧化氢酶。","过氧化物酶体蛋白的引导信号为PTS1或PTS2，故为答案。","过氧化物酶体可由ER出芽生成，也可由已有酶体分裂产生。"]},{"id":"ch05_fill_8","modI":0,"q":"Rubisco的小亚基由________基因编码,翻译后转运入叶绿体________。","a":"核,基质","kp":"ch05_s0_11","oe":["Rubisco小亚基由核基因编码，大亚基由叶绿体基因编码。","小亚基在胞质合成后经转运肽导入叶绿体基质，再与rbcL大亚基装配。"]},{"id":"ch05_fill_9","modI":1,"q":"亲核蛋白通过核孔复合体是________运输过程,需消耗________。","a":"主动,能量","kp":"ch05_s1_13","oe":["亲核蛋白经核孔复合体是主动、选择性的运输过程，故填主动。","该运输依赖Ran-GTP水解供能，故需消耗能量，填能量。"]},{"id":"ch05_fill_10","modI":1,"q":"NPC的纵向结构包括胞质面的________环和核质面的________结构。","a":"胞质(外),核篮","kp":"ch05_s1_4","oe":["NPC胞质面有胞质环，并伸出胞质纤维，故第一空填胞质环。","NPC核质面有核篮状结构，故第二空填核篮。"]},{"id":"ch05_fill_11","modI":0,"q":"类囊体腔蛋白的转运肽分2区:________序列和导向________的序列。","a":"导向叶绿体基质,类囊体腔","kp":"ch05_s0_10","oe":["转运肽第一区引导蛋白进入叶绿体基质，故填导向叶绿体基质。","第二区引导蛋白由基质进一步进入类囊体腔，故填类囊体腔。"]},{"id":"ch05_fill_12","modI":1,"q":"亲核蛋白入核时,核内Ran-________结合importin,使其________货物蛋白。","a":"GTP,释放","kp":"ch05_s1_15","oe":["核内Ran与GTP结合成Ran-GTP，与importin结合致货物释放。","Ran-GTP结合importin使其构象改变，从而释放货物蛋白。"]}],"short":[{"id":"ch05_short_1","modI":0,"q":"简述线粒体蛋白质翻译后转运的过程。","a":"线粒体蛋白质的翻译后转运：\n\n【特点】\n线粒体绝大多数蛋白由核基因编码，在胞质游离核糖体合成后转运。\n\n【过程】\n①在细胞质基质中，含N端导肽(presequence)的前体蛋白与Hsp70结合，ATP→ADP，解折叠为松散结构；\n②前体蛋白的导肽与线粒体外膜受体识别；\n③在内外膜接触点，经外膜转运子TOM复合体进入；\n④经内膜转运子TIM复合体进入基质；\n⑤导肽被切除，蛋白在基质中重新折叠成活性形式；\n⑥部分蛋白进一步分选到内膜、膜间隙或外膜。\n\n【要点】\n①需N端导肽；②必须解折叠才能导入；③发生在内外膜接触点；④消耗能量(ATP)。\n\n【对比】叶绿体蛋白用转运肽(transit peptide)引导。","kp":"ch05_s0_1"},{"id":"ch05_short_2","modI":1,"q":"简述核孔复合体的结构及核质运输机制。","a":"核孔复合体(NPC)及核质运输：\n\n【结构】\n①所有真核细胞间期核普遍存在；\n②通道直径9-10nm，外径约120nm；\n③八重对称：胞质环(外环，8条短纤毛)、核质面的核篮结构。\n\n【运输功能(双功能)】\n①被动运输：离子、小分子代谢产物、40~60kDa以下小分子自由扩散出入；\n②主动运输：大分子经NLS/NES转运。\n\n【入核机制】\n①亲核蛋白含核定位信号(NLS，富含碱性氨基酸)；\n②胞质中importin(输入蛋白)识别并结合NLS，形成转运复合物；\n③经NPC入核；\n④核内Ran-GTP结合importin，释放货物蛋白；\n⑤importin回收出核。\n\n【出核机制】\n①货物含核输出信号(NES，富含亮氨酸)；\n②exportin识别NES，经NPC出核。\n\n【意义】\n实现核质双向物质交换，是基因表达调控的基础。","kp":"ch05_s1_2"},{"id":"ch05_short_3","modI":0,"q":"比较线粒体、叶绿体、过氧化物酶体蛋白的翻译后转运。","a":"三种细胞器蛋白翻译后转运的比较：\n\n| 细胞器 | 引导信号 | 转运子/受体 | 特点 |\n|---|---|---|---|\n| 线粒体 | N端导肽(presequence) | TOM/TIM复合体 | 在内外膜接触点转运，需解折叠 |\n| 叶绿体 | N端转运肽(transit peptide) | TOC/TIC复合体 | 转运肽分2区(基质+类囊体腔) |\n| 过氧化物酶体 | PTS1/PTS2 | Pex蛋白 | 可折叠后导入，有两种发生途径 |\n\n【共同点】\n①蛋白由核基因编码、胞质游离核糖体合成；\n②翻译后转运；\n③依赖N端信号序列；\n④信号序列被切除；\n⑤消耗能量。\n\n【不同点】\n①线粒体需完全解折叠(Hsp70)，过氧化物酶体可折叠导入；\n②叶绿体转运肽分两区，可进入基质和类囊体腔；\n③过氧化物酶体还有ER出芽从头形成途径。\n\n【意义】保证细胞器蛋白正确定位。","kp":"ch05_s0_8"},{"id":"ch05_short_4","modI":1,"q":"简述亲核蛋白入核转运的分子机制。","a":"亲核蛋白入核转运机制：\n\n【关键分子】\n①核定位信号(NLS)：亲核蛋白含有的特殊氨基酸序列，通常富含碱性氨基酸(如PKKKRKV)；\n②importin(输入蛋白)：胞质中的NLS受体；\n③Ran：核质运输的关键GTP酶。\n\n【过程】\n①NLS-亲核蛋白在细胞质中与importin识别并结合，形成转运复合物；\n②转运复合物经核孔复合体(NPC)进入细胞核；\n③核内Ran-GTP结合importin，使其构象改变，释放货物蛋白；\n④importin-Ran-GTP复合物返回细胞质，Ran水解GTP，importin循环使用。\n\n【特点】\n①主动运输，消耗能量；\n②方向性由Ran-GTP的核内浓度梯度决定。\n\n【对照出核】\n核输出信号(NES)+exportin介导出核。\n\n【意义】\n是基因表达调控、细胞周期等的基础。","kp":"ch05_s1_17"},{"id":"ch05_short_5","modI":0,"q":"简述叶绿体蛋白质的分选途径。","a":"叶绿体蛋白质的分选：\n\n【共同起点】\n细胞质游离核糖体中合成的前体蛋白N端含转运肽(transit peptide)。\n\n【分选途径】\n①叶绿体基质蛋白：转运肽引导经TOC/TIC进入基质→转运肽被切割→折叠成活性蛋白(如Rubisco小亚基)。\n②类囊体腔蛋白：转运肽分2区——N端导向叶绿体基质序列+接下来导向类囊体腔序列→先进入基质，再经类囊体膜进入腔→切除转运肽。\n③类囊体膜蛋白：转运肽引导到类囊体膜并整合。\n\n【特点】\n①转运肽分2区，可两步引导；\n②转运肽最终被切除；\n③部分蛋白需叶绿体自身蛋白(如cpSecA)协助。\n\n【意义】\n保证叶绿体各亚区室蛋白的正确定位，是叶绿体功能的基础。","kp":"ch05_s0_9"},{"id":"ch05_short_6","modI":2,"q":"简述过氧化物酶体的发生及蛋白导入。","a":"过氧化物酶体的发生及蛋白导入：\n\n【结构】\n单层膜围绕的细胞器，又称微体(microbody)，含氧化酶和过氧化氢酶。\n\n【蛋白合成】\n过氧化物酶体蛋白主要在细胞质基质游离核糖体合成。\n\n【两种发生途径】\n①从头形成：过氧化物酶体的一些膜蛋白Pex3/Pex16来自内质网，由ER出芽形成新的过氧化物酶体；\n②分裂：由已有过氧化物酶体分裂产生。\n\n【蛋白导入】\n①经PTS1(多数蛋白，C端SKL序列)或PTS2(少数)信号；\n②由Pex蛋白(受体)识别；\n③可折叠状态即可导入(与线粒体需解折叠不同)。\n\n【意义】\n保证过氧化物酶体的生物发生和功能(脂肪酸氧化、过氧化氢分解)。","kp":"ch05_s2_1"}],"calc":[{"id":"ch05_calc_1","modI":0,"q":"论述蛋白质翻译后转运的主要途径及分子机制。","a":"翻译后转运将胞质合成的蛋白运往线粒体/叶绿体/过氧化物酶体/细胞核,机制各异","steps":"【定义】\n蛋白质在细胞质游离核糖体完全合成后，再转运至特定细胞器。\n\n【1. 线粒体蛋白转运】\n①N端导肽；②Hsp70+ATP解折叠；③内外膜接触点经TOM/TIM；④导肽切除、重折叠。\n\n【2. 叶绿体蛋白转运】\n①N端转运肽(分2区)；②经TOC/TIC；③分选到基质/类囊体腔/膜；④转运肽切除。\n\n【3. 过氧化物酶体蛋白转运】\n①PTS1/PTS2信号；②Pex受体；③可折叠导入；④两种发生途径(ER出芽/分裂)。\n\n【4. 核孔运输】\n①NLS/NES信号；②importin/exportin受体；③经NPC；④Ran-GTP调控。\n\n【共同点】\n①蛋白由核基因编码、胞质合成；②翻译后转运；③依赖信号序列；④信号被切除(部分)；⑤消耗能量。\n\n【意义】\n保证细胞器蛋白正确定位，维持细胞区室化功能。","kp":"ch05_s0_0"},{"id":"ch05_calc_2","modI":1,"q":"论述细胞核与细胞质之间物质运输的机制及意义。","a":"核质运输通过核孔复合体实现,由NLS/NES和Ran-GTP精密调控","steps":"【结构基础】\n核孔复合体(NPC)：通道直径9-10nm，外径约120nm，八重对称(胞质环+核篮)，间期核普遍存在。\n\n【运输类型】\n①被动运输：40~60kDa以下小分子自由扩散；\n②主动运输：大分子经NLS/NES。\n\n【入核机制】\n①亲核蛋白含NLS(富含碱性氨基酸)；\n②胞质importin识别结合NLS；\n③经NPC入核；\n④核内Ran-GTP结合importin释放货物。\n\n【出核机制】\n①货物含NES(富含亮氨酸)；\n②exportin识别NES，经NPC出核。\n\n【方向性】\nRan-GTP在核内浓度高、胞质低→决定运输方向。\n\n【意义】\n①实现核质物质交换(蛋白、RNA)；\n②是基因表达调控的基础(转录因子入核)；\n③参与细胞周期、信号转导、病毒感染等；\n④核质运输异常与疾病相关。","kp":"ch05_s1_6"},{"id":"ch05_calc_3","modI":0,"q":"论述细胞器蛋白靶向信号(分选信号)的多样性及其意义。","a":"不同细胞器使用不同的靶向信号,构成蛋白质分选的'邮政编码'系统","steps":"【各类靶向信号】\n①信号肽(signal peptide)：N端引导蛋白入ER(共翻译转移)；\n②导肽(presequence)：N端引导线粒体蛋白；\n③转运肽(transit peptide)：N端引导叶绿体蛋白(分2区)；\n④PTS1/PTS2：过氧化物酶体蛋白；\n⑤NLS：核定位信号(入核)；\n⑥NES：核输出信号(出核)；\n⑦KDEL：ER驻留/回收信号；\n⑧M6P：溶酶体酶分选信号。\n\n【共同特点】\n①都是特定的氨基酸序列(或糖基修饰)；\n②被特异受体识别；\n③部分在完成任务后被切除；\n④引导蛋白到达正确部位。\n\n【意义】\n①是蛋白质分选的分子基础('邮政编码')；\n②保证细胞区室化、各细胞器功能正常；\n③信号异常导致疾病(如家族性高胆固醇血症、I细胞病、囊性纤维化等)；\n④是基因工程中蛋白定位改造的基础。","kp":"ch05_s0_9"}],"term":[{"id":"ch05_term_1","modI":0,"term":"导肽(Presequence)","def":"①线粒体蛋白N端的引导序列（定义）。②功能：引导前体蛋白进入线粒体，与膜受体识别（功能）。③特点：完成使命后被切除（特点）。④与叶绿体的转运肽(transit peptide)相对应（对比）。","kps":"踩分点:①定义(1分)②功能(1分)③切除(1分)④与转运肽对比(1分)","kp":"ch05_s0_2"},{"id":"ch05_term_2","modI":0,"term":"转运肽(Transit Peptide)","def":"①叶绿体前体蛋白N端的引导序列（定义）。②特点：可分2区(导向叶绿体基质+导向类囊体腔)，完成使命后被切除（特点）。③功能：引导叶绿体蛋白分选到基质、类囊体腔或膜（功能）。","kps":"踩分点:①定义(1分)②分2区(1分)③切除(1分)④功能(1分)","kp":"ch05_s0_8"},{"id":"ch05_term_3","modI":1,"term":"核孔复合体(NPC)","def":"①真核细胞间期核膜上介导核质物质交换的通道复合体（定义）。②结构：通道直径9-10nm，外径约120nm，八重对称(胞质环+核篮)（结构）。③功能：双功能——被动运输(40~60kDa以下小分子)、主动运输(NLS/NES大分子)（功能）。","kps":"踩分点:①定义(1分)②结构(1分)③双功能(2分)","kp":"ch05_s1_2"},{"id":"ch05_term_4","modI":1,"term":"核定位信号(NLS)","def":"①亲核蛋白含有的、引导其进入细胞核的特殊氨基酸序列（定义）。②特点：通常富含碱性氨基酸(如PKKKRKV)（特点）。③机制：被胞质importin识别结合，经NPC入核（机制）。","kps":"踩分点:①定义(1分)②富含碱性氨基酸(1分)③机制(1分)","kp":"ch05_s1_11"},{"id":"ch05_term_5","modI":1,"term":"核输出信号(NES)","def":"①核内物质输出细胞核的信号序列（定义）。②特点：通常富含亮氨酸（特点）。③机制：被exportin识别，经核孔出核（机制）。","kps":"踩分点:①定义(1分)②富含亮氨酸(1分)③机制(1分)","kp":"ch05_s1_14"},{"id":"ch05_term_6","modI":1,"term":"输入蛋白(Importin)","def":"①胞质溶胶中的NLS受体（定义）。②功能：识别并结合亲核蛋白的NLS，形成转运复合物，经NPC入核（功能）。③调控：核内Ran-GTP结合importin使其释放货物（调控）。","kps":"踩分点:①定义(1分)②功能(1分)③Ran-GTP调控(1分)","kp":"ch05_s1_15"},{"id":"ch05_term_7","modI":1,"term":"Ran蛋白","def":"①核质运输的关键GTP酶（定义）。②功能：Ran-GTP(主要在核内)结合importin使其释放货物蛋白，决定运输方向（功能）。③意义：Ran-GTP的核内浓度梯度是核质运输方向性的基础（意义）。","kps":"踩分点:①定义(1分)②功能(2分)③意义(1分)","kp":"ch05_s1_16"},{"id":"ch05_term_8","modI":0,"term":"TOM/TIM复合体","def":"①线粒体外膜(TOM)和内膜(TIM)的蛋白转运子复合体（定义）。②功能：前体蛋白经TOM进入、经TIM进入线粒体基质（功能）。③位置：在内外膜接触点协同工作（位置）。","kps":"踩分点:①定义(1分)②功能(2分)③位置(1分)","kp":"ch05_s0_4"},{"id":"ch05_term_9","modI":2,"term":"过氧化物酶体(Peroxisome)","def":"①单层膜围绕的细胞器，又称微体(microbody)（定义）。②组成：含氧化酶和过氧化氢酶（组成）。③发生：两种途径——ER出芽从头形成、已有酶体分裂（发生）。④蛋白导入：经PTS1/PTS2信号（导入）。","kps":"踩分点:①定义(1分)②组成(1分)③发生(1分)④PTS信号(1分)","kp":"ch05_s2_0"},{"id":"ch05_term_10","modI":0,"term":"分子伴侣Hsp70在线粒体蛋白转运中的作用","def":"①Hsp70在胞质中与前体蛋白结合（定义）。②功能：消耗ATP使前体蛋白解折叠为松散结构，才能被导入线粒体（功能）。③意义：线粒体只允许解折叠蛋白进入（意义）。","kps":"踩分点:①定义(1分)②功能(2分)③意义(1分)","kp":"ch05_s0_7"},{"id":"ch05_term_11","modI":0,"term":"共翻译转移与翻译后转移","def":"①共翻译转移：蛋白边合成边经信号肽引导入ER(分泌蛋白、膜蛋白、溶酶体酶)（定义）。②翻译后转移：蛋白在游离核糖体完全合成后转运至线粒体、叶绿体、过氧化物酶体、细胞核（定义）。③区别：转移时间不同、信号序列不同、受体不同（区别）。","kps":"踩分点:①共翻译(1分)②翻译后(1分)③区别(2分)","kp":"ch05_s0_0"},{"id":"ch05_term_12","modI":1,"term":"核篮结构","def":"①核孔复合体核质面一侧的篮状结构（定义）。②组成：由8条纤丝汇聚成环（组成）。③功能：参与核质物质运输（功能）。","kps":"踩分点:①定义(1分)②组成(1分)③功能(1分)","kp":"ch05_s1_5"},{"id":"ch05_term_13","modI":2,"term":"PTS信号","def":"①过氧化物酶体蛋白的靶向信号(PTS1/PTS2)（定义）。②PTS1：多数过氧化物酶体蛋白，C端SKL序列；PTS2：少数蛋白，N端（分类）。③功能：由Pex蛋白受体识别，引导蛋白导入过氧化物酶体（功能）。","kps":"踩分点:①定义(1分)②PTS1/PTS2(2分)③功能(1分)","kp":"ch05_s2_2"},{"id":"ch05_term_14","modI":0,"term":"接触点(Contact Site)","def":"①线粒体内外膜靠近的区域（定义）。②功能：前体蛋白在此经TOM/TIM转运到线粒体基质（功能）。③意义：是线粒体蛋白导入的关键位点（意义）。","kps":"踩分点:①定义(1分)②功能(2分)③意义(1分)","kp":"ch05_s0_3"},{"id":"ch05_term_15","modI":0,"term":"细胞器蛋白靶向信号","def":"①引导蛋白质到达特定细胞器的氨基酸序列（定义）。②种类：信号肽(ER)、导肽(线粒体)、转运肽(叶绿体)、PTS(过氧化物酶体)、NLS/NES(核)、KDEL(ER驻留)、M6P(溶酶体)（种类）。③意义：是蛋白质分选的'邮政编码'，信号异常导致疾病（意义）。","kps":"踩分点:①定义(1分)②种类(2分)③意义(1分)","kp":"ch05_s0_7"}],"preview":{"main":"本章讲述蛋白质在细胞质合成后如何被定向转运到线粒体、叶绿体、细胞核和过氧化物酶体等膜包被细胞器。核心逻辑是：不同细胞器使用不同的信号序列和转运机制，其中线粒体和叶绿体依赖解折叠转运，细胞核通过核孔复合体进行信号介导的主动运输，过氧化物酶体则有独特的形成途径。理解这些机制是理解细胞区室化和蛋白质分选的基础。","questions":["线粒体蛋白的转运为什么要求前体蛋白必须解折叠？Hsp70在其中起什么作用？","线粒体膜的转运子（TOM/TIM）如何协同完成基质蛋白的导入？接触点转运意味着什么？","叶绿体蛋白的转运肽如何决定蛋白最终定位到基质、类囊体膜还是类囊体腔？双区转运肽有何特殊之处？","核孔复合体的结构（胞质环、核篮等）如何支持其双向运输功能？","核定位信号（NLS）和核输出信号（NES）分别如何被识别？Ran-GTP如何驱动入核和出核的方向性？","过氧化物酶体的两种形成途径分别是什么？其蛋白导入与线粒体、叶绿体有何本质区别？"]},"appcards":[{"front":"简述线粒体蛋白质翻译后转运的过程。","back":"线粒体蛋白质的翻译后转运：\n\n【特点】\n线粒体绝大多数蛋白由核基因编码，在胞质游离核糖体合成后转运。\n\n【过程】\n①在细胞质基质中，含N端导肽(presequence)的前体蛋白与Hsp70结合，ATP→ADP，解折叠为松散结构；\n②前体蛋白的导肽与线粒体外膜受体识别；\n③在内外膜接触点，经外膜转运子TOM复合体进入；\n④经内膜转运子TIM复合体进入基质；\n⑤导肽被切除，蛋白在基质中重新折叠成活性形式；\n⑥部分蛋白进一步分选到内膜、膜间隙或外膜。\n\n【要点】\n①需N端导肽；②必须解折叠才能导入；③发生在内外膜接触点；④消耗能量(ATP)。\n\n【对比】叶绿体蛋白用转运肽(transit peptide)引导。","points":"","mod":0,"modName":"模块一：线粒体与叶绿体蛋白转运","level":"掌握","src":"题库"},{"front":"简述核孔复合体的结构及核质运输机制。","back":"核孔复合体(NPC)及核质运输：\n\n【结构】\n①所有真核细胞间期核普遍存在；\n②通道直径9-10nm，外径约120nm；\n③八重对称：胞质环(外环，8条短纤毛)、核质面的核篮结构。\n\n【运输功能(双功能)】\n①被动运输：离子、小分子代谢产物、40~60kDa以下小分子自由扩散出入；\n②主动运输：大分子经NLS/NES转运。\n\n【入核机制】\n①亲核蛋白含核定位信号(NLS，富含碱性氨基酸)；\n②胞质中importin(输入蛋白)识别并结合NLS，形成转运复合物；\n③经NPC入核；\n④核内Ran-GTP结合importin，释放货物蛋白；\n⑤importin回收出核。\n\n【出核机制】\n①货物含核输出信号(NES，富含亮氨酸)；\n②exportin识别NES，经NPC出核。\n\n【意义】\n实现核质双向物质交换，是基因表达调控的基础。","points":"","mod":1,"modName":"模块二：核孔运输","level":"掌握","src":"题库"},{"front":"比较线粒体、叶绿体、过氧化物酶体蛋白的翻译后转运。","back":"三种细胞器蛋白翻译后转运的比较：\n\n| 细胞器 | 引导信号 | 转运子/受体 | 特点 |\n|---|---|---|---|\n| 线粒体 | N端导肽(presequence) | TOM/TIM复合体 | 在内外膜接触点转运，需解折叠 |\n| 叶绿体 | N端转运肽(transit peptide) | TOC/TIC复合体 | 转运肽分2区(基质+类囊体腔) |\n| 过氧化物酶体 | PTS1/PTS2 | Pex蛋白 | 可折叠后导入，有两种发生途径 |\n\n【共同点】\n①蛋白由核基因编码、胞质游离核糖体合成；\n②翻译后转运；\n③依赖N端信号序列；\n④信号序列被切除；\n⑤消耗能量。\n\n【不同点】\n①线粒体需完全解折叠(Hsp70)，过氧化物酶体可折叠导入；\n②叶绿体转运肽分两区，可进入基质和类囊体腔；\n③过氧化物酶体还有ER出芽从头形成途径。\n\n【意义】保证细胞器蛋白正确定位。","points":"","mod":0,"modName":"模块一：线粒体与叶绿体蛋白转运","level":"掌握","src":"题库"},{"front":"简述亲核蛋白入核转运的分子机制。","back":"亲核蛋白入核转运机制：\n\n【关键分子】\n①核定位信号(NLS)：亲核蛋白含有的特殊氨基酸序列，通常富含碱性氨基酸(如PKKKRKV)；\n②importin(输入蛋白)：胞质中的NLS受体；\n③Ran：核质运输的关键GTP酶。\n\n【过程】\n①NLS-亲核蛋白在细胞质中与importin识别并结合，形成转运复合物；\n②转运复合物经核孔复合体(NPC)进入细胞核；\n③核内Ran-GTP结合importin，使其构象改变，释放货物蛋白；\n④importin-Ran-GTP复合物返回细胞质，Ran水解GTP，importin循环使用。\n\n【特点】\n①主动运输，消耗能量；\n②方向性由Ran-GTP的核内浓度梯度决定。\n\n【对照出核】\n核输出信号(NES)+exportin介导出核。\n\n【意义】\n是基因表达调控、细胞周期等的基础。","points":"","mod":1,"modName":"模块二：核孔运输","level":"掌握","src":"题库"},{"front":"简述叶绿体蛋白质的分选途径。","back":"叶绿体蛋白质的分选：\n\n【共同起点】\n细胞质游离核糖体中合成的前体蛋白N端含转运肽(transit peptide)。\n\n【分选途径】\n①叶绿体基质蛋白：转运肽引导经TOC/TIC进入基质→转运肽被切割→折叠成活性蛋白(如Rubisco小亚基)。\n②类囊体腔蛋白：转运肽分2区——N端导向叶绿体基质序列+接下来导向类囊体腔序列→先进入基质，再经类囊体膜进入腔→切除转运肽。\n③类囊体膜蛋白：转运肽引导到类囊体膜并整合。\n\n【特点】\n①转运肽分2区，可两步引导；\n②转运肽最终被切除；\n③部分蛋白需叶绿体自身蛋白(如cpSecA)协助。\n\n【意义】\n保证叶绿体各亚区室蛋白的正确定位，是叶绿体功能的基础。","points":"","mod":0,"modName":"模块一：线粒体与叶绿体蛋白转运","level":"掌握","src":"题库"},{"front":"简述过氧化物酶体的发生及蛋白导入。","back":"过氧化物酶体的发生及蛋白导入：\n\n【结构】\n单层膜围绕的细胞器，又称微体(microbody)，含氧化酶和过氧化氢酶。\n\n【蛋白合成】\n过氧化物酶体蛋白主要在细胞质基质游离核糖体合成。\n\n【两种发生途径】\n①从头形成：过氧化物酶体的一些膜蛋白Pex3/Pex16来自内质网，由ER出芽形成新的过氧化物酶体；\n②分裂：由已有过氧化物酶体分裂产生。\n\n【蛋白导入】\n①经PTS1(多数蛋白，C端SKL序列)或PTS2(少数)信号；\n②由Pex蛋白(受体)识别；\n③可折叠状态即可导入(与线粒体需解折叠不同)。\n\n【意义】\n保证过氧化物酶体的生物发生和功能(脂肪酸氧化、过氧化氢分解)。","points":"","mod":2,"modName":"模块三：过氧化物酶体","level":"掌握","src":"题库"},{"front":"论述蛋白质翻译后转运的主要途径及分子机制。","back":"【定义】\n蛋白质在细胞质游离核糖体完全合成后，再转运至特定细胞器。\n\n【1. 线粒体蛋白转运】\n①N端导肽；②Hsp70+ATP解折叠；③内外膜接触点经TOM/TIM；④导肽切除、重折叠。\n\n【2. 叶绿体蛋白转运】\n①N端转运肽(分2区)；②经TOC/TIC；③分选到基质/类囊体腔/膜；④转运肽切除。\n\n【3. 过氧化物酶体蛋白转运】\n①PTS1/PTS2信号；②Pex受体；③可折叠导入；④两种发生途径(ER出芽/分裂)。\n\n【4. 核孔运输】\n①NLS/NES信号；②importin/exportin受体；③经NPC；④Ran-GTP调控。\n\n【共同点】\n①蛋白由核基因编码、胞质合成；②翻译后转运；③依赖信号序列；④信号被切除(部分)；⑤消耗能量。\n\n【意义】\n保证细胞器蛋白正确定位，维持细胞区室化功能。","points":"","mod":0,"modName":"模块一：线粒体与叶绿体蛋白转运","level":"掌握","src":"题库"},{"front":"论述细胞核与细胞质之间物质运输的机制及意义。","back":"【结构基础】\n核孔复合体(NPC)：通道直径9-10nm，外径约120nm，八重对称(胞质环+核篮)，间期核普遍存在。\n\n【运输类型】\n①被动运输：40~60kDa以下小分子自由扩散；\n②主动运输：大分子经NLS/NES。\n\n【入核机制】\n①亲核蛋白含NLS(富含碱性氨基酸)；\n②胞质importin识别结合NLS；\n③经NPC入核；\n④核内Ran-GTP结合importin释放货物。\n\n【出核机制】\n①货物含NES(富含亮氨酸)；\n②exportin识别NES，经NPC出核。\n\n【方向性】\nRan-GTP在核内浓度高、胞质低→决定运输方向。\n\n【意义】\n①实现核质物质交换(蛋白、RNA)；\n②是基因表达调控的基础(转录因子入核)；\n③参与细胞周期、信号转导、病毒感染等；\n④核质运输异常与疾病相关。","points":"","mod":1,"modName":"模块二：核孔运输","level":"掌握","src":"题库"},{"front":"论述细胞器蛋白靶向信号(分选信号)的多样性及其意义。","back":"【各类靶向信号】\n①信号肽(signal peptide)：N端引导蛋白入ER(共翻译转移)；\n②导肽(presequence)：N端引导线粒体蛋白；\n③转运肽(transit peptide)：N端引导叶绿体蛋白(分2区)；\n④PTS1/PTS2：过氧化物酶体蛋白；\n⑤NLS：核定位信号(入核)；\n⑥NES：核输出信号(出核)；\n⑦KDEL：ER驻留/回收信号；\n⑧M6P：溶酶体酶分选信号。\n\n【共同特点】\n①都是特定的氨基酸序列(或糖基修饰)；\n②被特异受体识别；\n③部分在完成任务后被切除；\n④引导蛋白到达正确部位。\n\n【意义】\n①是蛋白质分选的分子基础('邮政编码')；\n②保证细胞区室化、各细胞器功能正常；\n③信号异常导致疾病(如家族性高胆固醇血症、I细胞病、囊性纤维化等)；\n④是基因工程中蛋白定位改造的基础。","points":"","mod":0,"modName":"模块一：线粒体与叶绿体蛋白转运","level":"掌握","src":"题库"},{"front":"线粒体蛋白与叶绿体蛋白的N端信号序列有何异同？","back":"同：均为N端信号序列，引导后翻译转运，进入后切除；异：线粒体称导肽，叶绿体称转运肽；叶绿体类囊体腔蛋白转运肽含双区，分两步引导。","points":"N端信号；导肽/转运肽；切除；双区","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么只有去折叠的蛋白才能被导入线粒体？","back":"线粒体膜转运通道狭窄；折叠蛋白体积大无法通过TOM/TIM通道；胞质Hsp70结合前体蛋白，ATP水解使其解折叠为松散结构后才能导入。","points":"通道狭窄；Hsp70；ATP；解折叠","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"线粒体基质蛋白导入过程中，导肽被切除有什么意义？","back":"导肽切除使蛋白失去入线粒体信号；避免成熟蛋白被再次转运；允许蛋白折叠成活性构象；保证蛋白定位于基质。","points":"失去信号；避免再转运；折叠；定位","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较线粒体外膜转运子TOM与内膜转运子TIM的功能。","back":"TOM位于外膜，识别并结合前体蛋白N端导肽，使其进入膜间隙；TIM位于内膜，接收前体蛋白并转运至基质；二者在接触点协同完成跨膜转运。","points":"TOM外膜；识别导肽；TIM内膜；接触点协同","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么线粒体蛋白转运发生在内外膜接触点？","back":"接触点是内外膜靠近的区域；TOM与TIM在此对齐形成连续通道；前体蛋白可一次性穿过两层膜；提高转运效率，避免膜间隙中停留。","points":"内外膜靠近；TOM/TIM对齐；连续通道；效率","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明叶绿体蛋白的多层次分选。","back":"Rubisco小亚基由核基因编码，转运肽引导入基质后切除并折叠；类囊体腔蛋白转运肽含双区，先入基质再入类囊体腔；类囊体膜蛋白另有导入途径。","points":"Rubisco基质；类囊体腔双区；类囊体膜；多层次","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"叶绿体类囊体腔蛋白的转运肽为什么需要双区结构？","back":"N端第一区导向叶绿体基质；第二区导向类囊体腔；分两步引导，先进入基质再进入类囊体腔；保证蛋白正确定位于类囊体腔。","points":"双区；基质；类囊体腔；两步","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若细胞质Hsp70功能被抑制，线粒体蛋白导入会怎样？","back":"前体蛋白无法解折叠；保持折叠状态不能通过TOM/TIM通道；线粒体基质蛋白导入受阻；线粒体功能受损。","points":"不能解折叠；通道受阻；导入受阻；功能受损","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"核孔复合体NPC的被动运输与主动运输有何区别？","back":"被动运输：离子、小分子代谢物、约40~60kDa以下小分子自由扩散；主动运输：大分子经NLS/NES信号、消耗能量转运。","points":"小分子自由扩散；大分子；NLS/NES；耗能","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"核定位信号NLS有什么特点？举例说明其作用。","back":"NLS通常富含碱性氨基酸，如PKKKRKV；引导亲核蛋白入核；NLS与importin结合形成转运复合物；经NPC入核后Ran-GTP使其释放。","points":"碱性氨基酸；PKKKRKV；importin；Ran-GTP","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较NLS与NES的功能差异。","back":"NLS引导蛋白入核，富含碱性氨基酸；NES引导核内物质出核，通常富含亮氨酸；二者分别介导入核和出核转运。","points":"NLS入核；碱性；NES出核；亮氨酸","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么亲核蛋白入核需要importin？","back":"亲核蛋白不能直接穿过核孔；importin是水溶性NLS受体；识别并结合NLS形成转运复合物；介导蛋白通过NPC进入核内。","points":"不能直接穿过；NLS受体；转运复合物；NPC","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"Ran-GTP在核质运输中有什么作用？","back":"Ran-GTP主要在核内；结合importin使其构象改变；释放货物蛋白；Ran是核质运输关键调控GTP酶；维持入核与出核方向性。","points":"核内；结合importin；释放货物；GTP酶；方向性","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若Ran-GTP水解被抑制，核质运输会怎样？","back":"importin无法释放货物蛋白；入核转运复合物不能解离；货物蛋白不能释放到核内；核质运输受阻。","points":"不能释放；复合物不解离；货物滞留；运输受阻","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"过氧化物酶体蛋白的PTS1与PTS2信号有何不同？","back":"PTS1位于C端，多数过氧化物酶体基质蛋白使用；PTS2位于N端，少数蛋白使用；二者均引导蛋白导入过氧化物酶体。","points":"PTS1 C端；PTS2 N端；引导导入；基质蛋白","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"过氧化物酶体有哪两种形成途径？","back":"从头形成：由内质网出芽形成；分裂形成：由已有过氧化物酶体分裂；膜蛋白Pex3/Pex16来自内质网；蛋白经PTS信号导入。","points":"ER出芽；分裂；Pex3/Pex16；PTS","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说过氧化物酶体既是自主形成又依赖内质网？","back":"部分膜蛋白Pex3/Pex16来自内质网；新过氧化物酶体可由ER出芽从头形成；也可由已有过氧化物酶体分裂；蛋白主要在胞质游离核糖体合成后导入。","points":"Pex3/Pex16；ER出芽；分裂；胞质合成","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明后翻译转运在细胞中的普遍性。","back":"线粒体基质蛋白：胞质合成后经TOM/TIM导入；叶绿体Rubisco小亚基：经转运肽入基质；亲核蛋白：经NLS/importin入核；过氧化物酶体蛋白：经PTS导入。","points":"线粒体；叶绿体；细胞核；过氧化物酶体","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"线粒体蛋白定向运输中，导肽与受体识别有什么意义？","back":"保证蛋白特异性识别线粒体；导肽与TOM受体结合启动转运；避免其他蛋白误入；确保蛋白正确定位于线粒体。","points":"特异性；TOM受体；启动转运；正确定位","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较线粒体与叶绿体蛋白转运的异同。","back":"同：核基因编码、胞质合成、N端信号、后翻译转运、信号切除；异：线粒体称导肽，叶绿体称转运肽；叶绿体有类囊体腔双区转运肽。","points":"核基因；N端信号；后翻译；导肽/转运肽；双区","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"核孔复合体NPC的结构如何支持其双功能？","back":"胞质环有8条短纤毛伸向胞质；核质面有核篮由8条纤丝汇聚成环；中央通道直径9-10nm；结构支持被动扩散和主动转运。","points":"胞质环；核篮；中央通道；被动/主动","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若NPC的核篮结构缺失，可能影响什么？","back":"核质面纤丝汇聚结构异常；可能影响核输出或入核复合物定位；大分子主动转运效率下降；核质物质交换受阻。","points":"核篮缺失；复合物定位；主动转运；交换受阻","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么大蛋白入核需要NLS而小分子不需要？","back":"小分子约40~60kDa以下可经NPC自由扩散；大蛋白不能自由通过；需NLS与importin结合；经主动运输消耗能量入核。","points":"小分子自由扩散；大蛋白不能；NLS；主动运输","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明NLS和NES在细胞中的协同作用。","back":"染色质包装蛋白含NLS，经importin入核；核内某些分子含NES，经exportin出核；Ran-GTP调控方向；实现核质双向运输。","points":"NLS入核；NES出核；Ran-GTP；双向","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若线粒体TOM复合体功能缺失，细胞会怎样？","back":"前体蛋白不能识别线粒体外膜；不能进入膜间隙；TIM无法接收前体蛋白；线粒体基质蛋白导入受阻；线粒体功能受损。","points":"不能识别；不能进入；TIM受阻；线粒体受损","mod":null,"modName":"应用综合","level":"掌握","src":"生成"}]};